package com.lazybones;

import com.lazybones.alchemy.AlchemyIds;
import com.lazybones.alchemy.AlchemyItem;
import com.lazybones.alchemy.CupboardMap;
import com.lazybones.alchemy.FreeItemReader;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameObject;

/**
 * The Alchemist's Playground: mark whatever is free to convert.
 *
 * This room never touches the client's hint arrow. The arena plugin points it at the 30-point
 * cupboard here, and there is only one, so taking it would move that plugin's marker.
 */
@Singleton
public class AlchemyRoom implements ArenaRoom {

    private static final String FOUND = "You found:";

    private final Client client;
    private final LazyBonesConfig config;
    private final LazyBonesState state;
    private final FreeItemReader freeItemReader;

    private final GameObject[] cupboards = new GameObject[CupboardMap.CUPBOARDS];
    private final CupboardMap map = new CupboardMap();

    // The cupboard whose contents the next "You found:" describes.
    private int lastSearched = -1;

    @Inject
    AlchemyRoom(Client client, LazyBonesConfig config, LazyBonesState state, FreeItemReader freeItemReader) {
        this.client = client;
        this.config = config;
        this.state = state;
        this.freeItemReader = freeItemReader;
    }

    @Override
    public Room room() {
        return Room.ALCHEMY;
    }

    public void onGameObjectSpawned(GameObject object) {
        int index = AlchemyIds.cupboardIndex(object.getId());
        if (index < 0) {
            return;
        }
        cupboards[index] = object;
        if (AlchemyIds.isClosed(object.getId())) {
            // The cupboards stand open; one shutting means the items are being swapped.
            map.invalidate();
            lastSearched = -1;
        }
    }

    public void onGameObjectDespawned(GameObject object) {
        int index = AlchemyIds.cupboardIndex(object.getId());
        if (index >= 0 && cupboards[index] == object) {
            cupboards[index] = null;
        }
    }

    /** A game message. Only "You found: X" matters, and only for the cupboard just searched. */
    public void onChatMessage(String message) {
        if (message == null || !message.contains(FOUND)) {
            return;
        }
        AlchemyItem found = AlchemyItem.fromText(message.replace(FOUND, ""));
        if (found == null) {
            return;
        }
        int cupboard = lastSearched >= 0 ? lastSearched : nearestCupboard();
        if (cupboard >= 0) {
            map.solve(cupboard, found);
        }
        lastSearched = -1;
    }

    public void onCupboardClicked(int cupboardIndex) {
        lastSearched = cupboardIndex;
    }

    @Override
    public void onTick() {
        if (!config.showFreeItems()) {
            state.clearAlchemy();
            return;
        }

        List<AlchemyItem> free = freeItemReader.freeItems();
        if (free.isEmpty()) {
            state.clearAlchemy();
            return;
        }

        Set<Integer> ids = new HashSet<>();
        List<GameObject> marks = new ArrayList<>();
        for (AlchemyItem item : free) {
            ids.add(item.itemId());
            int cupboard = map.cupboardFor(item);
            if (cupboard >= 0 && cupboards[cupboard] != null) {
                marks.add(cupboards[cupboard]);
            }
        }
        state.setFreeItemIds(ids);
        state.setFreeCupboards(marks.isEmpty() ? Collections.emptyList() : marks);
    }

    @Override
    public void standDown() {
        state.clearAlchemy();
    }

    @Override
    public void reset() {
        state.clearAlchemy();
        map.invalidate();
        lastSearched = -1;
        for (int i = 0; i < cupboards.length; i++) {
            cupboards[i] = null;
        }
    }

    /**
     * The scene is reloading. No spawn or close event tells us when a rotation happens while the
     * player is out of the arena, so the cached cupboard positions and the solved mapping may no
     * longer be valid on return - drop them and wait for a fresh search.
     */
    public void onSceneLoading() {
        state.clearAlchemy();
        map.invalidate();
        lastSearched = -1;
        for (int i = 0; i < cupboards.length; i++) {
            cupboards[i] = null;
        }
    }

    /** Fallback when no click was seen: the game only tells you about the one you are standing at. */
    private int nearestCupboard() {
        if (client.getLocalPlayer() == null) {
            return -1;
        }
        int nearest = -1;
        int best = Integer.MAX_VALUE;
        for (int i = 0; i < cupboards.length; i++) {
            if (cupboards[i] == null) {
                continue;
            }
            int distance = cupboards[i].getWorldLocation().distanceTo(client.getLocalPlayer().getWorldLocation());
            if (distance < best) {
                best = distance;
                nearest = i;
            }
        }
        return nearest;
    }
}

package com.lazybones;

/**
 * Which alchemy spell to watch in the Alchemist's Playground. Both pay the same coins in this room
 * and share a cooldown, so the choice is Magic experience against rune cost.
 *
 * Public because a @ConfigItem returning a package-private enum throws IllegalAccessError when the
 * settings panel builds its dropdown.
 */
public enum AlchemySpell {
    LOW_LEVEL("Low Level Alchemy", RoomSpell.LOW_ALCHEMY),
    HIGH_LEVEL("High Level Alchemy", RoomSpell.HIGH_ALCHEMY);

    private final String displayName;
    private final RoomSpell roomSpell;

    AlchemySpell(String displayName, RoomSpell roomSpell) {
        this.displayName = displayName;
        this.roomSpell = roomSpell;
    }

    public RoomSpell roomSpell() { return roomSpell; }

    @Override
    public String toString() { return displayName; }
}

package com.lazybones;

/**
 * One arena room's behaviour. The plugin ticks the room the player is in and stands the others
 * down, so a room can never act while the player is somewhere else - the loop is the gate.
 */
public interface ArenaRoom {

    Room room();

    /** The player is in this room and it is switched on. */
    void onTick();

    /** The player is elsewhere. Stop guiding, but keep whatever is expensive to rebuild. */
    void standDown();

    /** Full teardown. The plugin's shutDown path. */
    void reset();
}

package com.lazybones;

/** Why a room's spell can or cannot be cast right now. */
public enum Availability {
    AVAILABLE,
    WRONG_SPELLBOOK,
    NOT_UNLOCKED,
    LEVEL,
    MISSING_RUNES,
    UNKNOWN
}

package com.lazybones;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ImageComponent;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

public class CastPromptOverlay extends OverlayPanel {

    private final LazyBonesState state;
    private final SpriteManager spriteManager;

    private int loadedSpriteId = -1;
    private BufferedImage icon;

    @Inject
    CastPromptOverlay(LazyBonesState state, SpriteManager spriteManager) {
        this.state = state;
        this.spriteManager = spriteManager;
        setPosition(OverlayPosition.TOP_CENTER);
    }

    @Override
    public Dimension render(Graphics2D g) {
        if (state.phase() != Phase.CAST || state.spell() == null) {
            return null;
        }
        SpellStatus status = state.spellStatus();
        if (status != null && !status.castable()) {
            return null; // RoomStatusOverlay is saying why instead
        }
        ensureIcon(state.castSpriteId());

        panelComponent.getChildren().clear();
        if (icon != null) {
            panelComponent.getChildren().add(new ImageComponent(icon));
        }
        panelComponent.getChildren().add(TitleComponent.builder()
            .text("Cast " + state.spell())
            .color(Color.YELLOW)
            .build());

        int spare = state.spareToEat();
        if (spare > 0) {
            panelComponent.getChildren().add(LineComponent.builder()
                .left("Spare to eat")
                .right(Integer.toString(spare))
                .rightColor(Color.GREEN)
                .build());
        }
        return super.render(g);
    }

    private void ensureIcon(int spriteId) {
        if (spriteId <= 0 || spriteId == loadedSpriteId) {
            return;
        }
        loadedSpriteId = spriteId;
        icon = null;
        spriteManager.getSpriteAsync(spriteId, 0, img -> icon = Sprites.scale2x(img));
    }
}

package com.lazybones;

public final class ClickCalculator {
    private ClickCalculator() {}

    private static final int BONES_PER_TYPE = 4; // nominal cadence; forecast only
    private static final int MAX_VALUE = 4;

    /**
     * Fewest clicks on one pile to bring heldValue up to the spell's target. For a spell that fills
     * exactly (bananas) the count stops one click short of overfilling so it never spills, and a pile
     * whose next bone would overfill returns 0. For a spell that only needs a threshold (peaches, 24
     * for the point cap) the final click may overshoot, since a spill past 24 costs nothing.
     *
     * @param heldValue        current held fruit-value
     * @param capacity         fruit that will fit after a cast (28 - other items)
     * @param spell            configured spell (supplies the target rule)
     * @param pileCurrentValue the pile's current bone value (1..4), from its live object id
     * @param takenOfThisType  bones already taken of the current type (0..3); forecasts the flip
     * @return click count (>= 0); 0 means already at target, or no click fits without overfilling
     */
    public static int clicksToTarget(int heldValue, int capacity, Spell spell,
                                     int pileCurrentValue, int takenOfThisType) {
        int target = spell.target(capacity);
        if (heldValue >= target) {
            return 0;
        }
        int v = heldValue;
        int value = pileCurrentValue;
        int taken = takenOfThisType;
        int clicks = 0;
        // Stop at the target, or one click short of overfilling - whichever comes first. Each pass
        // raises v by at least 1 until it can't, so this always terminates; the bound is a backstop.
        while (v < target && clicks < GraveyardIds.INVENTORY_SIZE) {
            if (!spell.allowsOverfill() && v + value > capacity) {
                break; // bananas must fill without spilling; peaches may overshoot to reach the point cap
            }
            v += value;
            clicks++;
            taken++;
            if (taken >= BONES_PER_TYPE) {
                taken = 0;
                value = value >= MAX_VALUE ? 1 : value + 1; // cycle 1->2->3->4->1
            }
        }
        return clicks;
    }
}

package com.lazybones;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Shape;
import javax.inject.Inject;
import net.runelite.api.GameObject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

public class DepositOverlay extends Overlay {

    private final LazyBonesState state;
    private final LazyBonesConfig config;

    @Inject
    DepositOverlay(LazyBonesState state, LazyBonesConfig config) {
        this.state = state;
        this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D g) {
        // Show the chute from the moment you are full (CAST) through the deposit, so you can click it and
        // cast Bones to X on the way; casting flips CAST -> DEPOSIT and the chute guidance carries through.
        Phase phase = state.phase();
        if (phase != Phase.CAST && phase != Phase.DEPOSIT) {
            return null;
        }
        GameObject chute = state.chute();
        if (chute == null) {
            return null;
        }
        Shape hull = chute.getConvexHull();
        if (hull != null) {
            OverlayUtil.renderPolygon(g, hull, config.highlightColor());
        }
        return null;
    }
}

package com.lazybones;

/**
 * Which enchant to watch. Auto keeps up with your Magic level but stops at Lvl-6, whose rune cost
 * is already steep for one more point a cast; pick a level yourself to go higher or lower.
 *
 * Public because a @ConfigItem returning a package-private enum throws IllegalAccessError when the
 * settings panel builds its dropdown.
 */
public enum EnchantChoice {
    AUTO("Auto (highest, no Lvl-7)", null),
    LVL_1("Lvl-1 Enchant", RoomSpell.ENCHANT_1),
    LVL_2("Lvl-2 Enchant", RoomSpell.ENCHANT_2),
    LVL_3("Lvl-3 Enchant", RoomSpell.ENCHANT_3),
    LVL_4("Lvl-4 Enchant", RoomSpell.ENCHANT_4),
    LVL_5("Lvl-5 Enchant", RoomSpell.ENCHANT_5),
    LVL_6("Lvl-6 Enchant", RoomSpell.ENCHANT_6),
    LVL_7("Lvl-7 Enchant", RoomSpell.ENCHANT_7);

    /** Highest first, so the auto rule takes the first one that fits. Lvl-7 is deliberately absent. */
    private static final RoomSpell[] AUTO_ORDER = {
        RoomSpell.ENCHANT_6, RoomSpell.ENCHANT_5, RoomSpell.ENCHANT_4,
        RoomSpell.ENCHANT_3, RoomSpell.ENCHANT_2, RoomSpell.ENCHANT_1,
    };

    private final String displayName;
    private final RoomSpell fixed;

    EnchantChoice(String displayName, RoomSpell fixed) {
        this.displayName = displayName;
        this.fixed = fixed;
    }

    /** @return the spell to watch. Never null - below every requirement it still names Lvl-1. */
    public RoomSpell resolve(int boostedMagic) {
        if (fixed != null) {
            return fixed;
        }
        for (RoomSpell enchant : AUTO_ORDER) {
            if (boostedMagic >= enchant.levelRequirement()) {
                return enchant;
            }
        }
        return RoomSpell.ENCHANT_1;
    }

    @Override
    public String toString() { return displayName; }
}

package com.lazybones;

import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.ProgressBarComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/** The bonus shape, how much of its window is gone, and a nudge about dragonstones. */
public class EnchantPanelOverlay extends OverlayPanel {

    private static final String STONES_LINE = "Pick up dragonstones";

    // Sized to its contents for the same reason the room status panel is: the default panel width is
    // narrower than the dragonstone line, and a shape name sits beside it. Measured and capped the
    // same way, so the two panels stay the same shape on screen.
    private static final int WIDTH_MARGIN = 20;
    private static final int MAX_PANEL_WIDTH = 250;

    private final LazyBonesState state;
    private final LazyBonesConfig config;

    @Inject
    EnchantPanelOverlay(LazyBonesState state, LazyBonesConfig config) {
        this.state = state;
        this.config = config;
        setPosition(OverlayPosition.TOP_LEFT);
    }

    @Override
    public Dimension render(Graphics2D g) {
        EnchantView view = state.enchantView();
        boolean stones = !state.dragonstones().isEmpty();
        if (view == null && !stones) {
            return null;
        }

        boolean bar = view != null && config.showBonusBar();
        FontMetrics metrics = g.getFontMetrics();
        int[] lineWidths = {
            bar ? metrics.stringWidth(view.shape().displayName()) : 0,
            stones ? metrics.stringWidth(STONES_LINE) : 0
        };
        panelComponent.setPreferredSize(new Dimension(PanelWidth.fit(lineWidths, WIDTH_MARGIN, MAX_PANEL_WIDTH), 0));

        panelComponent.getChildren().clear();

        if (bar) {
            panelComponent.getChildren().add(TitleComponent.builder()
                .text(view.shape().displayName())
                .color(config.bonusPileColor())
                .build());

            ProgressBarComponent progress = new ProgressBarComponent();
            progress.setMinimum(0);
            progress.setMaximum(view.windowTicks());
            progress.setForegroundColor(config.bonusPileColor());
            if (view.timingKnown()) {
                // Fills as the window is spent, so a full bar means move now.
                progress.setValue(view.windowTicks() - view.ticksLeft());
                progress.setCenterLabel(seconds(view.ticksLeft()));
            } else {
                // Nothing to show until a change has been seen; the shape alone is still useful.
                progress.setValue(0);
                progress.setCenterLabel("--");
            }
            progress.setLabelDisplayMode(ProgressBarComponent.LabelDisplayMode.TEXT_ONLY);
            panelComponent.getChildren().add(progress);
        }

        if (stones) {
            panelComponent.getChildren().add(LineComponent.builder()
                .left(STONES_LINE)
                .leftColor(config.dragonstoneColor())
                .build());
        }

        return panelComponent.getChildren().isEmpty() ? null : super.render(g);
    }

    /** One tick is 0.6 seconds, so a whole window reads as a countdown rather than a tick count. */
    private static String seconds(int ticks) {
        return String.format("%.1fs", ticks * 0.6);
    }
}

package com.lazybones;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Shape;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

/** Outlines the bonus shape's pile with its pickup count, and every dragonstone on the floor. */
public class EnchantSceneOverlay extends Overlay {

    private static final int COUNT_Z_OFFSET = 160;

    private final Client client;
    private final LazyBonesState state;
    private final LazyBonesConfig config;

    @Inject
    EnchantSceneOverlay(Client client, LazyBonesState state, LazyBonesConfig config) {
        this.client = client;
        this.state = state;
        this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D g) {
        drawDragonstones(g);
        drawBonusPile(g);
        return null;
    }

    private void drawDragonstones(Graphics2D g) {
        Color color = config.dragonstoneColor();
        for (WorldPoint stone : state.dragonstones()) {
            LocalPoint local = LocalPoint.fromWorld(client, stone);
            if (local == null) {
                continue; // off the loaded scene
            }
            Polygon tile = Perspective.getCanvasTilePoly(client, local);
            if (tile != null) {
                OverlayUtil.renderPolygon(g, tile, color);
            }
        }
    }

    private void drawBonusPile(Graphics2D g) {
        EnchantView view = state.enchantView();
        if (view == null || view.bonusPile() == null) {
            return;
        }
        GameObject pile = view.bonusPile();
        Color color = config.bonusPileColor();

        Shape hull = pile.getConvexHull();
        if (hull != null) {
            OverlayUtil.renderPolygon(g, hull, color);
        }

        if (view.pickups() == EnchantView.NO_COUNT) {
            return;
        }
        g.setFont(FontManager.getRunescapeBoldFont());
        String text = Integer.toString(view.pickups());
        Point loc = Perspective.getCanvasTextLocation(client, g, pile.getLocalLocation(), text, COUNT_Z_OFFSET);
        if (loc != null) {
            OutlinedText.draw(g, loc.getX(), loc.getY(), text, color);
        }
    }
}

package com.lazybones;

import com.lazybones.enchant.Shape;
import net.runelite.api.GameObject;

/** One tick's worth of what the enchanting overlays draw. Immutable, swapped whole. */
public final class EnchantView {

    /** The pickup count when the setting is off, so the overlay knows to draw nothing. */
    public static final int NO_COUNT = -1;

    private final Shape shape;
    private final GameObject bonusPile;
    private final boolean timingKnown;
    private final int ticksLeft;
    private final int windowTicks;
    private final int pickups;

    public EnchantView(Shape shape, GameObject bonusPile, boolean timingKnown,
                       int ticksLeft, int windowTicks, int pickups) {
        this.shape = shape;
        this.bonusPile = bonusPile;
        this.timingKnown = timingKnown;
        this.ticksLeft = ticksLeft;
        this.windowTicks = windowTicks;
        this.pickups = pickups;
    }

    public Shape shape() { return shape; }
    public GameObject bonusPile() { return bonusPile; }
    public boolean timingKnown() { return timingKnown; }
    public int ticksLeft() { return ticksLeft; }
    public int windowTicks() { return windowTicks; }
    public int pickups() { return pickups; }
}

package com.lazybones;

import com.lazybones.enchant.BonusShapeTracker;
import com.lazybones.enchant.PickupCalculator;
import com.lazybones.enchant.Shape;
import com.lazybones.enchant.TickModel;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.Tile;
import net.runelite.api.TileItem;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;

/**
 * The Enchanting Chamber: which shape is worth the bonus, how long that lasts, and how many more to
 * pick up before it changes.
 *
 * This room never touches the client's hint arrow. Core points it at the nearest dragonstone here,
 * and there is only one arrow, so taking it would move that plugin's marker.
 */
@Singleton
public class EnchantingRoom implements ArenaRoom {

    private final Client client;
    private final LazyBonesConfig config;
    private final LazyBonesState state;

    private final BonusShapeTracker tracker = new BonusShapeTracker();
    private final List<GameObject> piles = new ArrayList<>();
    private final List<WorldPoint> dragonstones = new ArrayList<>();

    @Inject
    EnchantingRoom(Client client, LazyBonesConfig config, LazyBonesState state) {
        this.client = client;
        this.config = config;
        this.state = state;
    }

    @Override
    public Room room() {
        return Room.ENCHANTMENT;
    }

    public void onGameObjectSpawned(GameObject object) {
        if (Shape.fromPileObjectId(object.getId()) != null) {
            piles.add(object);
        }
    }

    public void onGameObjectDespawned(GameObject object) {
        // Compares by identity, not equals() - the list now holds every pile of every shape, and two
        // distinct piles of the same shape must never be treated as the same object just because the
        // concrete GameObject happens to compare equal.
        Iterator<GameObject> it = piles.iterator();
        while (it.hasNext()) {
            if (it.next() == object) {
                it.remove();
                return;
            }
        }
    }

    public void onItemSpawned(TileItem item, Tile tile) {
        if (item.getId() == ItemID.MAGICTRAINING_DRAGONSTONE) {
            dragonstones.add(tile.getWorldLocation());
        }
    }

    public void onItemDespawned(TileItem item, Tile tile) {
        if (item.getId() == ItemID.MAGICTRAINING_DRAGONSTONE) {
            dragonstones.remove(tile.getWorldLocation());
        }
    }

    /**
     * The scene is reloading, so the pile references are about to be stale. The window anchor goes
     * with them: a hop or a relog restarts the client's tick count, and no GameTick fires in between
     * for standDown() to catch it.
     */
    public void onSceneLoading() {
        tracker.clear();
        piles.clear();
        dragonstones.clear();
    }

    @Override
    public void onTick() {
        int now = client.getTickCount();
        tracker.observe(visibleShape(), now);

        // The stones have their own setting and are worth double a shape, so they are published
        // first. An indicator we cannot read is no reason to stop outlining them.
        state.setDragonstones(config.highlightDragonstones()
            ? new ArrayList<>(dragonstones)
            : Collections.emptyList());

        Shape shape = tracker.shape();
        if (shape == null) {
            state.setEnchantView(null);
            return;
        }

        TickModel model = new TickModel(config.windowTicks(), config.enchantTicks(),
            config.pickupTicks(), config.bufferTicks());

        boolean known = tracker.known();
        int ticksLeft = known ? PickupCalculator.ticksLeft(tracker.elapsedTicks(now), model) : 0;
        int pickups = EnchantView.NO_COUNT;
        if (known && config.showPickupCount()) {
            pickups = PickupCalculator.pickups(ticksLeft, heldShapes(), model);
        }

        state.setEnchantView(new EnchantView(shape, nearestPile(shape), known,
            ticksLeft, model.windowTicks(), pickups));
    }

    @Override
    public void standDown() {
        state.clearEnchanting();
        // Whatever the window was doing while we were away, we did not watch it. Coming back is
        // walking in again: the shape shows at once, the clock waits for the next change.
        tracker.clear();
    }

    @Override
    public void reset() {
        state.clearEnchanting();
        tracker.clear();
        piles.clear();
        dragonstones.clear();
    }

    /**
     * MAGICTRAIN_ENCH_BONUSTXT is a static label - it always reads "Bonus:" and never names a shape.
     * The interface shows the bonus shape by swapping which of the four model widgets is unhidden, so
     * that is what has to be read instead. Anything other than exactly one visible model - none, more
     * than one, or a missing widget - means the shape cannot be told, so this returns null.
     */
    private Shape visibleShape() {
        Widget cube = client.getWidget(InterfaceID.MagictrainingEncha.MAGICTRAIN_CUBE);
        Widget cylinder = client.getWidget(InterfaceID.MagictrainingEncha.MAGICTRAIN_CYLINDER);
        Widget pentamid = client.getWidget(InterfaceID.MagictrainingEncha.MAGICTRAIN_PENTAMID);
        Widget icosahedron = client.getWidget(InterfaceID.MagictrainingEncha.MAGICTRAIN_ICOSAHEDRON);
        if (cube == null || cylinder == null || pentamid == null || icosahedron == null) {
            return null;
        }

        Shape found = null;
        int visible = 0;
        if (!cube.isHidden()) { found = Shape.CUBE; visible++; }
        if (!cylinder.isHidden()) { found = Shape.CYLINDER; visible++; }
        if (!pentamid.isHidden()) { found = Shape.PENTAMID; visible++; }
        if (!icosahedron.isHidden()) { found = Shape.ICOSAHEDRON; visible++; }
        return visible == 1 ? found : null;
    }

    /**
     * The room holds 24 piles of each shape, spread out over the floor - not one pile per shape. The
     * one worth walking to is whichever is closest right now, so this is recomputed every tick rather
     * than cached. No player position, or no loaded pile of that shape, means nothing gets marked.
     */
    private GameObject nearestPile(Shape shape) {
        Player localPlayer = client.getLocalPlayer();
        if (localPlayer == null) {
            return null;
        }
        WorldPoint at = localPlayer.getWorldLocation();

        GameObject nearest = null;
        int nearestDistance = Integer.MAX_VALUE;
        for (GameObject pile : piles) {
            if (Shape.fromPileObjectId(pile.getId()) != shape) {
                continue;
            }
            int distance = pile.getWorldLocation().distanceTo(at);
            if (distance < nearestDistance) {
                nearestDistance = distance;
                nearest = pile;
            }
        }
        return nearest;
    }

    /** Un-enchanted shapes in the pack. Finished orbs are done and cost no more time. */
    private int heldShapes() {
        ItemContainer inventory = client.getItemContainer(InventoryID.INV);
        if (inventory == null) {
            return 0;
        }
        int held = 0;
        for (Item item : inventory.getItems()) {
            if (item == null) {
                continue;
            }
            for (Shape shape : Shape.values()) {
                if (item.getId() == shape.itemId()) {
                    held++;
                    break;
                }
            }
        }
        return held;
    }
}

package com.lazybones;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import java.awt.Stroke;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/** Marks the cupboard holding the item that is free to convert. */
public class FreeItemOverlay extends Overlay {

    // Sits above the Mage Training Arena plugin's own cupboard item image (drawn at 150), so the two
    // markers stack rather than overlap when both land on the same cupboard.
    private static final int Z_OFFSET = 180;

    private static final int ARROW_WIDTH = 16;
    private static final int ARROW_HEIGHT = 14;
    private static final Color OUTLINE_COLOR = new Color(0, 0, 0, 180);
    private static final Stroke OUTLINE_STROKE = new BasicStroke(2f);

    private final Client client;
    private final LazyBonesState state;
    private final LazyBonesConfig config;

    @Inject
    FreeItemOverlay(Client client, LazyBonesState state, LazyBonesConfig config) {
        this.client = client;
        this.state = state;
        this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D g) {
        if (state.freeCupboards().isEmpty()) {
            return null;
        }
        Color color = config.freeItemColor();
        if (color == null) {
            return null;
        }
        for (GameObject cupboard : state.freeCupboards()) {
            Point at = Perspective.getCanvasTextLocation(client, g, cupboard.getLocalLocation(), "", Z_OFFSET);
            if (at != null) {
                drawArrow(g, at.getX(), at.getY(), color);
            }
        }
        return null;
    }

    // A downward-pointing triangle: the flat top sits at the anchor point and the tip drops toward
    // the cupboard, so the marker points at what it is marking instead of just floating over it.
    private static void drawArrow(Graphics2D g, int centerX, int topY, Color fill) {
        Polygon triangle = new Polygon();
        triangle.addPoint(centerX - ARROW_WIDTH / 2, topY);
        triangle.addPoint(centerX + ARROW_WIDTH / 2, topY);
        triangle.addPoint(centerX, topY + ARROW_HEIGHT);

        // The diagonals are short enough that without smoothing the edges stair-step badly. Put the
        // hint back afterwards so the rest of the frame draws as the client expects.
        Object was = g.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

        g.setColor(fill);
        g.fillPolygon(triangle);
        g.setStroke(OUTLINE_STROKE);
        g.setColor(OUTLINE_COLOR);
        g.drawPolygon(triangle);

        if (was != null) {
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, was);
        }
    }
}

