package com.lazybones;

import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.ObjectID;

/**
 * Central id table for the MTA Creature Graveyard.
 *
 * Named constants rather than transcribed numbers: ItemID carries three different BANANA values, and
 * copying the wrong one out would look exactly like copying the right one.
 */
public final class GraveyardIds {
    private GraveyardIds() {}

    // Bone pile objects - the object id encodes the current bone value (1..4).
    public static final int PILE_VALUE_1 = ObjectID.MAGICTRAINING_BONES_PILE1;
    public static final int PILE_VALUE_2 = ObjectID.MAGICTRAINING_BONES_PILE2;
    public static final int PILE_VALUE_3 = ObjectID.MAGICTRAINING_BONES_PILE3;
    public static final int PILE_VALUE_4 = ObjectID.MAGICTRAINING_BONES_PILE4;

    // Bone items (inventory).
    public static final int BONE_VALUE_1 = ItemID.MAGICTRAINING_BONES1;
    public static final int BONE_VALUE_2 = ItemID.MAGICTRAINING_BONES2;
    public static final int BONE_VALUE_3 = ItemID.MAGICTRAINING_BONES3;
    public static final int BONE_VALUE_4 = ItemID.MAGICTRAINING_BONES4;

    public static final int FOOD_CHUTE = ObjectID.MAGICTRAINING_GRAVE_FOODSHUTE;

    // The spells make ordinary fruit, not a minigame copy of it.
    public static final int BANANA = ItemID.BANANA;
    public static final int PEACH = ItemID.PEACH;

    public static final int INVENTORY_SIZE = 28;

    /** @return 1..4 fruit value for a bone item id, or 0 if it is not a graveyard bone. */
    public static int boneValue(int itemId) {
        switch (itemId) {
            case BONE_VALUE_1: return 1;
            case BONE_VALUE_2: return 2;
            case BONE_VALUE_3: return 3;
            case BONE_VALUE_4: return 4;
            default: return 0;
        }
    }

    /** @return 1..4 fruit value for a pile object id, or 0 if it is not a bone pile. */
    public static int pileValue(int objectId) {
        switch (objectId) {
            case PILE_VALUE_1: return 1;
            case PILE_VALUE_2: return 2;
            case PILE_VALUE_3: return 3;
            case PILE_VALUE_4: return 4;
            default: return 0;
        }
    }

    public static boolean isPile(int objectId) { return pileValue(objectId) != 0; }
    public static boolean isBone(int itemId) { return boneValue(itemId) != 0; }
}

package com.lazybones;

import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.HintArrowType;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.Widget;

/** The Creature Graveyard: count the pile, prompt the cast, point at the chute. */
@Singleton
public class GraveyardRoom implements ArenaRoom {

    @Override
    public Room room() {
        return Room.GRAVEYARD;
    }

    private final Client client;
    private final LazyBonesConfig config;
    private final GraveyardScene scene;
    private final LazyBonesState state;

    // Per-bone-id counts from the previous inventory change, to detect which bone id was just added.
    private final Map<Integer, Integer> lastBoneCounts = new HashMap<>();
    private boolean active;
    private boolean hintArrowSet;
    private WorldPoint hintArrowPoint;

    @Inject
    GraveyardRoom(Client client, LazyBonesConfig config, GraveyardScene scene, LazyBonesState state) {
        this.client = client;
        this.config = config;
        this.scene = scene;
        this.state = state;
    }

    public void onGameObjectSpawned(GameObject object) {
        scene.onSpawn(object);
    }

    public void onGameObjectDespawned(GameObject object) {
        scene.onDespawn(object);
    }

    public void onSceneLoading() {
        scene.onSceneLoading();
    }

    public void onPileClicked(WorldPoint location) {
        scene.noteClickedPile(location);
    }

    public void onInventoryChanged(ItemContainer container) {
        Map<Integer, Integer> counts = boneCounts(container);
        for (Map.Entry<Integer, Integer> c : counts.entrySet()) {
            int prev = lastBoneCounts.getOrDefault(c.getKey(), 0);
            if (c.getValue() > prev) {
                scene.onBoneTaken(GraveyardIds.boneValue(c.getKey()));
            }
        }
        lastBoneCounts.clear();
        lastBoneCounts.putAll(counts);
    }

    /** Full teardown, including the pile cycle state. The plugin's shutDown path. */
    @Override
    public void reset() {
        scene.clear();
        state.clear();
        lastBoneCounts.clear();
        releaseHintArrow();
        active = false;
    }

    /**
     * Stop guiding without forgetting the room. Called every tick the player is anywhere but the
     * graveyard, so it must not touch GraveyardScene: the pile and chute objects only arrive from
     * spawn events on a scene reload, so dropping them here would leave the graveyard dead after
     * switching the room off and on again, until the player left the region and came back.
     */
    @Override
    public void standDown() {
        state.clear();
        releaseHintArrow();
        active = false;
    }

    @Override
    public void onTick() {
        if (!scene.active()) {
            if (active) {
                reset(); // in the room with none of its objects loaded: start the count over
            }
            return;
        }
        active = true; // entering (or still inside) re-seeds from a fresh inventory read below

        if (client.getLocalPlayer() == null) {
            return;
        }
        Spell spell = config.spell();
        ItemContainer inv = client.getItemContainer(InventoryID.INV);
        Item[] items = inv == null ? null : inv.getItems();
        InventorySnapshot snap = InventoryReader.read(items, spell);
        Phase phase = PhaseModel.phaseFor(snap, spell);

        state.setSpell(spell);

        // Learn the spell's icon sprite from the spellbook widget whenever it is on screen, so the
        // cast prompt can show the real Bones to X icon even when the Magic tab is later closed.
        Widget spellWidget = client.getWidget(spell.spellWidgetId());
        if (spellWidget != null && spellWidget.getSpriteId() > 0) {
            state.setCastSpriteId(spellWidget.getSpriteId());
        }
        state.setSpareToEat(spareToEat(spell, snap));

        WorldPoint player = client.getLocalPlayer().getWorldLocation();
        if (phase == Phase.DEPOSIT) {
            state.setPhase(Phase.DEPOSIT);
            state.setPileMarks(Collections.emptyList());
            state.setChute(scene.nearestChute(player));
            updateHintArrow(Phase.DEPOSIT);
            return;
        }
        if (phase == Phase.CAST) {
            state.setPhase(Phase.CAST);
            state.setPileMarks(Collections.emptyList());
            state.setChute(scene.nearestChute(player)); // point at the chute now so you can click + cast en route
            updateHintArrow(Phase.CAST);
            return;
        }

        // COLLECT: highlight just the single nearest pile. If clicking it would overfill (bananas near a
        // full inventory) it shows nothing and the cast prompt takes over - underfilling by a slot or two
        // beats walking off to a smaller pile. Peaches never hit this: they may overshoot, so any pile fits.
        PileMark mark = null;
        List<GraveyardScene.PileHandle> nearest = scene.nearestPiles(player, 1);
        if (!nearest.isEmpty()) {
            GraveyardScene.PileHandle h = nearest.get(0);
            // Re-read the live object id each tick so the forecast can't lag an actual flip (see PileCycleState).
            h.state().syncToObjectValue(GraveyardIds.pileValue(h.object().getId()));
            int clicks = ClickCalculator.clicksToTarget(snap.heldValue(), snap.capacity(), spell,
                h.state().currentValue(), h.state().takenOfThisType());
            if (clicks > 0) {
                mark = new PileMark(h.object(), clicks);
            }
        }
        if (mark != null) {
            state.setPhase(Phase.COLLECT);
            state.setPileMarks(Collections.singletonList(mark));
            state.setChute(null);
            updateHintArrow(Phase.COLLECT);
        } else if (snap.heldValue() > 0) {
            // Holding bones but the nearest pile would overfill: you're full enough. Prompt the cast and
            // point at the chute now, so you can click it and cast Bones to X on the way over.
            state.setPhase(Phase.CAST);
            state.setPileMarks(Collections.emptyList());
            state.setChute(scene.nearestChute(player));
            updateHintArrow(Phase.CAST);
        } else {
            // Empty-handed and nothing here fits (inventory too full of other items): show nothing.
            state.setPhase(Phase.COLLECT);
            state.setPileMarks(Collections.emptyList());
            state.setChute(null);
            updateHintArrow(Phase.COLLECT);
        }
    }

    /**
     * Point the game's hint arrow at the chute. Set every tick rather than once: the arena plugin's
     * alchemy room clears the arrow on login whenever it is not inside its own room, so walking here
     * from there can drop ours, and re-setting makes that harmless.
     */
    private void updateHintArrow(Phase phase) {
        GameObject chute = state.chute();
        boolean want = config.showDepositArrow()
            && chute != null
            && (phase == Phase.CAST || phase == Phase.DEPOSIT);
        if (want) {
            WorldPoint at = chute.getWorldLocation();
            client.setHintArrow(at);
            hintArrowSet = true;
            hintArrowPoint = at;
        } else {
            releaseHintArrow();
        }
    }

    /**
     * Drop our hint arrow, but only if it is still ours. The client has a single arrow and the arena
     * plugin owns it in the other three rooms, so another plugin may have pointed it elsewhere since
     * we set it. Core does the same check in MiningPlugin.
     */
    private void releaseHintArrow() {
        if (!hintArrowSet) {
            return;
        }
        hintArrowSet = false;
        if (client.getHintArrowType() == HintArrowType.COORDINATE
            && hintArrowPoint != null
            && hintArrowPoint.equals(client.getHintArrowPoint())) {
            client.clearHintArrow();
        }
        hintArrowPoint = null;
    }

    private static Map<Integer, Integer> boneCounts(ItemContainer c) {
        Map<Integer, Integer> counts = new HashMap<>();
        if (c == null) {
            return counts;
        }
        for (Item it : c.getItems()) {
            if (it != null && GraveyardIds.isBone(it.getId())) {
                counts.merge(it.getId(), 1, Integer::sum);
            }
        }
        return counts;
    }

    // Peaches held past the 24 point-cap are free healing: after a cast you keep min(held, capacity)
    // peaches, and every one beyond 24 can be eaten without costing a point. Naturally 0 until you go over.
    private static int spareToEat(Spell spell, InventorySnapshot snap) {
        if (spell != Spell.BONES_TO_PEACHES) {
            return 0;
        }
        int peaches = Math.min(snap.heldValue(), snap.capacity());
        return Math.max(0, peaches - Spell.PEACH_POINT_CAP);
    }
}

package com.lazybones;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Singleton;
import net.runelite.api.GameObject;
import net.runelite.api.coords.WorldPoint;

/**
 * Tracks the graveyard's pile and chute objects in the loaded scene and owns per-pile cycle state.
 * Cycle state is keyed by world location and survives despawns and leaving the region; only clear()
 * drops it, and the plugin calls that on shutdown. Carrying stale state back into the region costs
 * nothing, because onSpawn re-anchors each pile to its object id, which is the authoritative value.
 * Also finds the nearest chute for the deposit phase.
 */
@Singleton
public class GraveyardScene {

    public static final class PileHandle {
        private final GameObject object;
        private final PileCycleState state;
        PileHandle(GameObject object, PileCycleState state) {
            this.object = object;
            this.state = state;
        }
        public GameObject object() { return object; }
        public PileCycleState state() { return state; }
    }

    private final Map<WorldPoint, GameObject> livePiles = new HashMap<>();
    private final Map<WorldPoint, GameObject> liveChutes = new HashMap<>();
    private final Map<WorldPoint, PileCycleState> cycleStates = new HashMap<>(); // persisted across despawns

    private WorldPoint lastClickedPile;

    public void onSpawn(GameObject o) {
        int id = o.getId();
        WorldPoint wp = o.getWorldLocation();
        if (GraveyardIds.isPile(id)) {
            livePiles.put(wp, o);
            PileCycleState st = cycleStates.get(wp);
            if (st == null) {
                cycleStates.put(wp, new PileCycleState(GraveyardIds.pileValue(id)));
            } else {
                st.syncToObjectValue(GraveyardIds.pileValue(id)); // authoritative re-read
            }
        } else if (id == GraveyardIds.FOOD_CHUTE) {
            liveChutes.put(wp, o);
        }
    }

    public void onDespawn(GameObject o) {
        WorldPoint wp = o.getWorldLocation();
        if (GraveyardIds.isPile(o.getId())) {
            livePiles.remove(wp); // keep cycleStates entry
        } else if (o.getId() == GraveyardIds.FOOD_CHUTE) {
            liveChutes.remove(wp);
        }
    }

    /**
     * The scene is reloading. Drop stale live object references but KEEP cycle state - this may be a
     * chunk reload while still inside the region, in which case the objects re-spawn the same cycle and
     * active() is true again by the next GameTick. If the player actually left, nothing re-spawns and
     * active() stays false; the plugin stands the room down and the cycle state waits for a return.
     */
    public void onSceneLoading() {
        livePiles.clear();
        liveChutes.clear();
        lastClickedPile = null;
    }

    public void noteClickedPile(WorldPoint wp) {
        this.lastClickedPile = wp;
    }

    /** A bone of the given value just entered the inventory; attribute it to the last-clicked pile. */
    public void onBoneTaken(int value) {
        if (lastClickedPile == null) {
            return;
        }
        PileCycleState st = cycleStates.get(lastClickedPile);
        if (st != null) {
            st.recordBoneReceived(value);
        }
        lastClickedPile = null;
    }

    public void clear() {
        livePiles.clear();
        liveChutes.clear();
        cycleStates.clear();
        lastClickedPile = null;
    }

    /** Active whenever any graveyard object is loaded - the plugin's region gate. */
    public boolean active() {
        return !livePiles.isEmpty() || !liveChutes.isEmpty();
    }

    public List<PileHandle> nearestPiles(WorldPoint player, int n) {
        List<WorldPoint> locs = new ArrayList<>(livePiles.keySet());
        List<PileHandle> out = new ArrayList<>();
        for (int i : SceneMath.nearestIndices(player, locs, n)) {
            WorldPoint wp = locs.get(i);
            out.add(new PileHandle(livePiles.get(wp), cycleStates.get(wp)));
        }
        return out;
    }

    public GameObject nearestChute(WorldPoint player) {
        List<WorldPoint> locs = new ArrayList<>(liveChutes.keySet());
        List<Integer> nearest = SceneMath.nearestIndices(player, locs, 1);
        return nearest.isEmpty() ? null : liveChutes.get(locs.get(nearest.get(0)));
    }
}

package com.lazybones;

import net.runelite.api.Item;

public final class InventoryReader {
    private InventoryReader() {}

    /**
     * @param items inventory slots (null => empty inventory); empty slots have id <= 0
     * @param spell the configured spell; its fruit item is counted as fruit
     */
    public static InventorySnapshot read(Item[] items, Spell spell) {
        int heldValue = 0;
        int fruitCount = 0;
        int other = 0; // non-bone, non-fruit, non-empty slots
        if (items != null) {
            for (Item item : items) {
                if (item == null) continue;
                int id = item.getId();
                if (id <= 0) continue; // empty slot
                int bv = GraveyardIds.boneValue(id);
                if (bv != 0) {
                    heldValue += bv;
                } else if (id == spell.fruitItemId()) {
                    fruitCount++; // fruit is only read as holdingFruit() (> 0); count slots, matching bones/other
                } else {
                    other++;
                }
            }
        }
        return new InventorySnapshot(heldValue, GraveyardIds.INVENTORY_SIZE - other, fruitCount);
    }
}

package com.lazybones;

/** Immutable read of the inventory relevant to the graveyard. */
public final class InventorySnapshot {
    private final int heldValue;
    private final int capacity;
    private final int fruitCount;

    public InventorySnapshot(int heldValue, int capacity, int fruitCount) {
        this.heldValue = heldValue;
        this.capacity = capacity;
        this.fruitCount = fruitCount;
    }

    public int heldValue() { return heldValue; }
    public int capacity() { return capacity; }
    public int fruitCount() { return fruitCount; }
    public boolean holdingFruit() { return fruitCount > 0; }
}

