package com.lazybones;

import com.google.inject.Provides;
import com.lazybones.alchemy.AlchemyIds;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.Skill;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.ItemDespawned;
import net.runelite.api.events.ItemSpawned;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
    name = "LazyBones",
    description = "Mage Training Arena Enhancements",
    tags = {"minigame", "mta", "bones", "magic", "skilling"}
)
public class LazyBonesPlugin extends Plugin {

    @Inject private Client client;
    @Inject private LazyBonesState state;
    @Inject private GraveyardRoom graveyardRoom;
    @Inject private AlchemyRoom alchemyRoom;
    @Inject private EnchantingRoom enchantingRoom;
    @Inject private OverlayManager overlayManager;
    @Inject private PileOverlay pileOverlay;
    @Inject private SpellOverlay spellOverlay;
    @Inject private DepositOverlay depositOverlay;
    @Inject private CastPromptOverlay castPromptOverlay;
    @Inject private LazyBonesConfig config;
    @Inject private MtaLocation location;
    @Inject private SpellbookReader spellbook;
    @Inject private MtaPluginStatus mtaStatus;
    @Inject private RoomStatusOverlay roomStatusOverlay;
    @Inject private ChatMessageManager chatMessageManager;
    @Inject private FreeItemOverlay freeItemOverlay;
    @Inject private FreeItemSlotOverlay freeItemSlotOverlay;
    @Inject private EnchantPanelOverlay enchantPanelOverlay;
    @Inject private EnchantSceneOverlay enchantSceneOverlay;

    // The arena-plugin nag is one line per session, not one per tick.
    private boolean mtaWarningSent;

    // Built in startUp so the tick loop does not allocate. Every room the plugin knows about.
    private final List<ArenaRoom> rooms = new ArrayList<>();

    @Provides
    LazyBonesConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(LazyBonesConfig.class);
    }

    @Override
    protected void startUp() {
        rooms.clear();
        rooms.add(graveyardRoom);
        rooms.add(alchemyRoom);
        rooms.add(enchantingRoom);

        overlayManager.add(pileOverlay);
        overlayManager.add(spellOverlay);
        overlayManager.add(depositOverlay);
        overlayManager.add(castPromptOverlay);
        overlayManager.add(roomStatusOverlay);
        overlayManager.add(freeItemOverlay);
        overlayManager.add(freeItemSlotOverlay);
        overlayManager.add(enchantPanelOverlay);
        overlayManager.add(enchantSceneOverlay);
    }

    @Override
    protected void shutDown() {
        overlayManager.remove(pileOverlay);
        overlayManager.remove(spellOverlay);
        overlayManager.remove(depositOverlay);
        overlayManager.remove(castPromptOverlay);
        overlayManager.remove(roomStatusOverlay);
        overlayManager.remove(freeItemOverlay);
        overlayManager.remove(freeItemSlotOverlay);
        overlayManager.remove(enchantPanelOverlay);
        overlayManager.remove(enchantSceneOverlay);
        state.clearRoomStatus();
        state.clearAlchemy();
        state.clearEnchanting();
        mtaWarningSent = false;
        for (ArenaRoom r : rooms) {
            r.reset();
        }
        rooms.clear();
        state.clear();
    }

    @Subscribe
    public void onGameObjectSpawned(GameObjectSpawned e) {
        graveyardRoom.onGameObjectSpawned(e.getGameObject());
        alchemyRoom.onGameObjectSpawned(e.getGameObject());
        enchantingRoom.onGameObjectSpawned(e.getGameObject());
    }

    @Subscribe
    public void onGameObjectDespawned(GameObjectDespawned e) {
        graveyardRoom.onGameObjectDespawned(e.getGameObject());
        alchemyRoom.onGameObjectDespawned(e.getGameObject());
        enchantingRoom.onGameObjectDespawned(e.getGameObject());
    }

    @Subscribe
    public void onItemSpawned(ItemSpawned e) {
        enchantingRoom.onItemSpawned(e.getItem(), e.getTile());
    }

    @Subscribe
    public void onItemDespawned(ItemDespawned e) {
        enchantingRoom.onItemDespawned(e.getItem(), e.getTile());
    }

    @Subscribe
    public void onChatMessage(ChatMessage e) {
        if (e.getType() == ChatMessageType.GAMEMESSAGE) {
            alchemyRoom.onChatMessage(e.getMessage());
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged e) {
        // Drop stale live object refs on scene reload; cycle state persists (see GraveyardScene.onSceneLoading).
        if (e.getGameState() == GameState.LOADING) {
            graveyardRoom.onSceneLoading();
            alchemyRoom.onSceneLoading();
            enchantingRoom.onSceneLoading();
        }
    }

    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked e) {
        MenuEntry entry = e.getMenuEntry();
        MenuAction type = entry.getType();
        if (isObjectAction(type) && GraveyardIds.isPile(entry.getIdentifier())) {
            WorldView wv = client.getTopLevelWorldView();
            WorldPoint wp = WorldPoint.fromScene(wv, entry.getParam0(), entry.getParam1(), wv.getPlane());
            graveyardRoom.onPileClicked(wp);
        }
        if (isObjectAction(type)) {
            int cupboard = AlchemyIds.cupboardIndex(entry.getIdentifier());
            if (cupboard >= 0) {
                alchemyRoom.onCupboardClicked(cupboard);
            }
        }
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged e) {
        if (e.getContainerId() != InventoryID.INV) {
            return;
        }
        graveyardRoom.onInventoryChanged(e.getItemContainer());
    }

    @Subscribe
    public void onGameTick(GameTick e) {
        Room room = location.current();
        state.setRoom(room);

        if (room == Room.NONE) {
            state.clearRoomStatus();
            tickRooms(Room.NONE, false);
            return;
        }

        // A room the user switched off gets no warnings of any kind, not just no guidance.
        boolean roomOn = roomEnabled(room);

        RoomSpell required = roomOn
            ? RoomSpell.forRoom(room, config, client.getBoostedSkillLevel(Skill.MAGIC))
            : null;
        state.setSpellStatus(required == null ? null : spellbook.status(required));

        MtaWarning warning = roomOn ? mtaStatus.warningFor(room) : MtaWarning.NONE;
        state.setMtaWarning(warning);
        if (warning != MtaWarning.NONE && !mtaWarningSent && config.warnMtaPlugin()) {
            // Posted on entering a room, never from startUp: a plugin enabled at client boot starts
            // before any chat widget exists and the message would go nowhere.
            chatMessageManager.queue(QueuedMessage.builder()
                .type(ChatMessageType.CONSOLE)
                .runeLiteFormattedMessage(WarningCopy.mtaLine(warning, room))
                .build());
            mtaWarningSent = true;
        }

        // All four rooms share one region on different planes and spawn events fire for every plane, so
        // the graveyard's objects are in scene from anywhere in the arena. Only the room the player is
        // actually standing in may guide, or the deposit arrow would fight the arena plugin's own.
        tickRooms(room, roomOn);
    }

    /**
     * Tick the room the player is in, stand the rest down. Doing this as a loop rather than a
     * branch per room is deliberate: a room that is never told to stand down keeps drawing into a
     * room it does not own, which is exactly the bug this shape prevents.
     */
    private void tickRooms(Room room, boolean roomOn) {
        for (ArenaRoom r : rooms) {
            if (r.room() == room && roomOn) {
                r.onTick();
            } else {
                r.standDown();
            }
        }
    }

    private boolean roomEnabled(Room room) {
        switch (room) {
            case GRAVEYARD:
                return config.roomGraveyard();
            case TELEKINETIC:
                return config.roomTelekinetic();
            case ALCHEMY:
                return config.roomAlchemy();
            case ENCHANTMENT:
                return config.roomEnchanting();
            default:
                return true;
        }
    }

    private static boolean isObjectAction(MenuAction a) {
        return a == MenuAction.GAME_OBJECT_FIRST_OPTION
            || a == MenuAction.GAME_OBJECT_SECOND_OPTION
            || a == MenuAction.GAME_OBJECT_THIRD_OPTION
            || a == MenuAction.GAME_OBJECT_FOURTH_OPTION
            || a == MenuAction.GAME_OBJECT_FIFTH_OPTION;
    }
}

package com.lazybones;

import java.util.Collections;
import java.util.List;
import java.util.Set;
import javax.inject.Singleton;
import net.runelite.api.GameObject;
import net.runelite.api.coords.WorldPoint;

/** Thread-visible render state: the plugin writes it each tick, the overlays read it. */
@Singleton
public class LazyBonesState {
    private volatile Phase phase;
    private volatile List<PileMark> pileMarks = Collections.emptyList();
    private volatile GameObject chute;
    private volatile Spell spell;
    private volatile int castSpriteId = -1; // spell-icon sprite id, learned from the spellbook widget
    private volatile int spareToEat;        // peaches held past 24 that can be eaten for free healing
    private volatile Room room = Room.NONE;
    private volatile SpellStatus spellStatus;
    private volatile MtaWarning mtaWarning = MtaWarning.NONE;
    private volatile List<GameObject> freeCupboards = Collections.emptyList();
    private volatile Set<Integer> freeItemIds = Collections.emptySet();
    private volatile EnchantView enchantView;
    private volatile List<WorldPoint> dragonstones = Collections.emptyList();

    public void setPhase(Phase phase) { this.phase = phase; }
    public void setPileMarks(List<PileMark> marks) { this.pileMarks = marks == null ? Collections.emptyList() : marks; }
    public void setChute(GameObject chute) { this.chute = chute; }
    public void setSpell(Spell spell) { this.spell = spell; }
    public void setCastSpriteId(int id) { this.castSpriteId = id; }
    public void setSpareToEat(int spare) { this.spareToEat = spare; }
    public void setRoom(Room room) { this.room = room == null ? Room.NONE : room; }
    public void setSpellStatus(SpellStatus status) { this.spellStatus = status; }
    public void setMtaWarning(MtaWarning warning) { this.mtaWarning = warning == null ? MtaWarning.NONE : warning; }
    public void setFreeCupboards(List<GameObject> cupboards) { this.freeCupboards = cupboards == null ? Collections.emptyList() : cupboards; }
    public void setFreeItemIds(Set<Integer> ids) { this.freeItemIds = ids == null ? Collections.emptySet() : ids; }
    public void setEnchantView(EnchantView view) { this.enchantView = view; }
    public void setDragonstones(List<WorldPoint> stones) {
        this.dragonstones = stones == null ? Collections.emptyList() : stones;
    }

    public Phase phase() { return phase; }
    public List<PileMark> pileMarks() { return pileMarks; }
    public GameObject chute() { return chute; }
    public Spell spell() { return spell; }
    public int castSpriteId() { return castSpriteId; }
    public int spareToEat() { return spareToEat; }
    public Room room() { return room; }
    public SpellStatus spellStatus() { return spellStatus; }
    public MtaWarning mtaWarning() { return mtaWarning; }
    public List<GameObject> freeCupboards() { return freeCupboards; }
    public Set<Integer> freeItemIds() { return freeItemIds; }
    public EnchantView enchantView() { return enchantView; }
    public List<WorldPoint> dragonstones() { return dragonstones; }

    public void clear() {
        phase = null;
        pileMarks = Collections.emptyList();
        chute = null;
    }

    /**
     * Room status is cleared apart from the graveyard's render state. The plugin writes the room, the
     * spell status and the arena warning every tick for whichever room the player is in, and on that
     * same tick the graveyard stands down and calls clear() for every room but its own - folding
     * these fields into clear() would blank the warning panel as fast as the plugin filled it in.
     */
    public void clearRoomStatus() {
        room = Room.NONE;
        spellStatus = null;
        mtaWarning = MtaWarning.NONE;
    }

    /** Alchemy marking only. Kept apart from clear() and clearRoomStatus() for the same reason. */
    public void clearAlchemy() {
        freeCupboards = Collections.emptyList();
        freeItemIds = Collections.emptySet();
    }

    /** Enchanting marking only. Kept apart from the other clears for the same reason they are. */
    public void clearEnchanting() {
        enchantView = null;
        dragonstones = Collections.emptyList();
    }
}

package com.lazybones;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;

/**
 * Which arena room the player is standing in. The Alchemist's Playground, Creature Graveyard and
 * Enchanting Chamber all sit in one region, on their own plane apiece, confirmed from the in-game
 * smoke run - so inside that region the plane picks the room, and the widget check afterward is just
 * a sanity check rather than the primary signal. A room's interface stays loaded after the player
 * walks out of it, so scanning widgets alone (the old approach) kept reporting whichever room had
 * been visited most recently in enum order, long after the player left it.
 *
 * The Telekinetic Theatre is not in that region - observed instanced, so its region id is not
 * something to depend on - and it has no plane of its own, so its widget is the only signal for it.
 * That matches how core's own MTA plugin identifies it.
 */
@Singleton
public class MtaLocation {

    /** The Alchemist's Playground, Creature Graveyard and Enchanting Chamber's shared region. */
    static final int MTA_REGION = 13462;

    private final Client client;

    @Inject
    MtaLocation(Client client) {
        this.client = client;
    }

    public Room current() {
        Player player = client.getLocalPlayer();
        if (player == null) {
            return Room.NONE;
        }

        WorldPoint location = player.getWorldLocation();
        if (location.getRegionID() == MTA_REGION) {
            Room room = Room.forPlane(location.getPlane());
            return room != Room.NONE && client.getWidget(room.rootComponent()) != null ? room : Room.NONE;
        }

        return client.getWidget(Room.TELEKINETIC.rootComponent()) != null ? Room.TELEKINETIC : Room.NONE;
    }
}

package com.lazybones;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

/**
 * Whether the Mage Training Arena plugin is doing its half of the work. LazyBones deliberately does
 * not draw what that plugin draws, so a room it has switched off is a room with a gap in it.
 *
 * Both key names are taken from the source rather than guessed. PluginManager stores a plugin's
 * enabled flag under the "runelite" group keyed by its class name lowercased, and the arena plugin's
 * own per-room keys are the literal keyName strings from MTAConfig.
 */
@Singleton
public class MtaPluginStatus {

    static final String RUNELITE_GROUP = "runelite";
    static final String MTA_PLUGIN_KEY = "mtaplugin";
    static final String MTA_GROUP = "mta";

    private final ConfigManager configManager;

    @Inject
    MtaPluginStatus(ConfigManager configManager) {
        this.configManager = configManager;
    }

    /** Unset reads as off: the arena plugin declares enabledByDefault = false. */
    public boolean pluginEnabled() {
        return Boolean.parseBoolean(configManager.getConfiguration(RUNELITE_GROUP, MTA_PLUGIN_KEY));
    }

    /** Unset reads as on: every room toggle in MTAConfig defaults to true. */
    public boolean roomEnabled(Room room) {
        String key = room.mtaConfigKey();
        if (key == null) {
            return true;
        }
        String value = configManager.getConfiguration(MTA_GROUP, key);
        return value == null || Boolean.parseBoolean(value);
    }

    public MtaWarning warningFor(Room room) {
        if (room == Room.NONE) {
            return MtaWarning.NONE;
        }
        if (!pluginEnabled()) {
            return MtaWarning.PLUGIN_OFF;
        }
        if (!roomEnabled(room)) {
            return MtaWarning.ROOM_OFF;
        }
        return MtaWarning.NONE;
    }
}

package com.lazybones;

/** What is missing from the Mage Training Arena plugin's side of the room. */
public enum MtaWarning {
    NONE,
    PLUGIN_OFF,
    ROOM_OFF
}

package com.lazybones;

import java.awt.Color;
import java.awt.Graphics2D;

/**
 * Counts drawn onto the scene sit on top of whatever the game is already rendering, including an
 * object's bright hover glow. A plain coloured string disappears into it, so every count the plugin
 * draws gets a solid black outline first.
 */
final class OutlinedText {
    private OutlinedText() {}

    /** Draw {@code text} at the baseline point, outlined in black. */
    static void draw(Graphics2D g, int x, int y, String text, Color color) {
        g.setColor(Color.BLACK);
        for (int dx = -1; dx <= 1; dx++) {
            for (int dy = -1; dy <= 1; dy++) {
                if (dx != 0 || dy != 0) {
                    g.drawString(text, x + dx, y + dy);
                }
            }
        }
        g.setColor(color);
        g.drawString(text, x, y);
    }
}

package com.lazybones;

/**
 * Picks how wide an overlay panel should draw itself: wide enough for its longest line plus a
 * margin, capped so one long line cannot stretch the panel across half the screen.
 */
final class PanelWidth {
    private PanelWidth() {}

    /** @return the widest of {@code lineWidths} plus {@code margin}, capped at {@code max}. */
    static int fit(int[] lineWidths, int margin, int max) {
        int widest = 0;
        for (int width : lineWidths) {
            widest = Math.max(widest, width);
        }
        return Math.min(widest + margin, max);
    }
}

package com.lazybones;

public final class PhaseModel {
    private PhaseModel() {}

    /** Derive the active phase purely from the inventory snapshot. Self-healing - no stored transitions. */
    public static Phase phaseFor(InventorySnapshot inv, Spell spell) {
        if (inv.holdingFruit()) {
            return Phase.DEPOSIT;
        }
        // Only "ready to cast" if you actually hold bones. Without this, a full inventory of non-bone
        // items (capacity 0, so target 0) reads as 0 >= 0 and falsely prompts a cast - walk in with a
        // full pack and the plugin tells you to convert bones you are not carrying.
        if (inv.heldValue() > 0 && inv.heldValue() >= spell.target(inv.capacity())) {
            return Phase.CAST;
        }
        return Phase.COLLECT;
    }
}

package com.lazybones;

/**
 * Per-pile forecast state. The pile's object id is authoritative for the current value; the
 * "4 per type" cadence is a forecast only and is abandoned the instant reality disagrees.
 */
public final class PileCycleState {
    private int currentValue;    // 1..4
    private int takenOfThisType; // 0..3

    public PileCycleState(int initialValue) {
        this.currentValue = initialValue;
        this.takenOfThisType = 0;
    }

    public int currentValue() { return currentValue; }
    public int takenOfThisType() { return takenOfThisType; }

    /** Re-read of the pile's visible value. Re-anchors and resets the count when it changes. */
    public void syncToObjectValue(int objectValue) {
        if (objectValue != 0 && objectValue != currentValue) {
            currentValue = objectValue;
            takenOfThisType = 0;
        }
    }

    /** A bone was confirmed taken from this pile. Snaps to the new type (count 1) if unexpected. */
    public void recordBoneReceived(int boneValue) {
        if (boneValue == 0) {
            return;
        }
        if (boneValue == currentValue) {
            takenOfThisType++;
            if (takenOfThisType >= 4) {
                currentValue = currentValue >= 4 ? 1 : currentValue + 1;
                takenOfThisType = 0;
            }
        } else {
            currentValue = boneValue;   // short run: resume standard 4/4/4/4 on the new type
            takenOfThisType = 1;
        }
    }
}

