package com.lazybones;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Shape;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

public class PileOverlay extends Overlay {

    private final Client client;
    private final LazyBonesState state;
    private final LazyBonesConfig config;

    @Inject
    PileOverlay(Client client, LazyBonesState state, LazyBonesConfig config) {
        this.client = client;
        this.state = state;
        this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D g) {
        if (state.phase() != Phase.COLLECT) {
            return null;
        }
        Color color = config.highlightColor();
        g.setFont(FontManager.getRunescapeBoldFont());
        for (PileMark mark : state.pileMarks()) {
            GameObject obj = mark.object();
            if (obj == null) {
                continue;
            }
            Shape hull = obj.getConvexHull();
            if (hull != null) {
                OverlayUtil.renderPolygon(g, hull, color);
            }
            if (config.showNumbers()) {
                String text = Integer.toString(mark.clicks());
                Point loc = Perspective.getCanvasTextLocation(client, g, obj.getLocalLocation(), text, 160);
                if (loc != null) {
                    OutlinedText.draw(g, loc.getX(), loc.getY(), text, color);
                }
            }
        }
        return null;
    }
}

package com.lazybones;

import net.runelite.api.gameval.InterfaceID;

/**
 * A Mage Training Arena room. The Alchemist's Playground, Creature Graveyard and Enchanting Chamber
 * share one region and one plane apiece, so the plane tells them apart. The Telekinetic Theatre sits
 * in its own region (observed instanced, so that region id is not something to depend on) and carries
 * no plane of its own - its interface is the only signal. The MTA plugin's per-room config key travels
 * with the room so the "that plugin is off" warning can name the right setting.
 */
public enum Room {
    // The -1 here is NO_PLANE below - enum constants are built before any other static member, so
    // they cannot reference it by name; a literal is the only option this early in the class.
    NONE(0, null, "", -1),
    TELEKINETIC(InterfaceID.MagictrainingTele.UNIVERSE, "telekinetic", "Telekinetic Theatre", -1),
    ALCHEMY(InterfaceID.MagictrainingAlchem.UNIVERSE, "alchemy", "Alchemist's Playground", 2),
    GRAVEYARD(InterfaceID.MagictrainingGrave.UNIVERSE, "graveyard", "Creature Graveyard", 1),
    ENCHANTMENT(InterfaceID.MagictrainingEncha.UNIVERSE, "enchantment", "Enchanting Chamber", 0);

    /** Plane for {@link #NONE} and {@link #TELEKINETIC}, neither of which is identified by plane. */
    public static final int NO_PLANE = -1;

    private final int rootComponent;
    private final String mtaConfigKey;
    private final String displayName;
    private final int plane;

    Room(int rootComponent, String mtaConfigKey, String displayName, int plane) {
        this.rootComponent = rootComponent;
        this.mtaConfigKey = mtaConfigKey;
        this.displayName = displayName;
        this.plane = plane;
    }

    public int rootComponent() { return rootComponent; }

    /** Key under the "mta" config group for this room's overlay, or null for {@link #NONE}. */
    public String mtaConfigKey() { return mtaConfigKey; }

    public String displayName() { return displayName; }

    /** The plane this room sits on inside the shared arena region, or {@link #NO_PLANE}. */
    public int plane() { return plane; }

    /**
     * The shared-region room that sits on the given plane, or {@link #NONE} if no room claims it.
     * {@link #TELEKINETIC} is never returned here - it is not in the shared region, so its own widget
     * is the only thing that identifies it.
     */
    public static Room forPlane(int plane) {
        for (Room room : values()) {
            if (room.plane == plane && room != NONE) {
                return room;
            }
        }
        return NONE;
    }
}

package com.lazybones;

import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;

/**
 * A spell a room needs. Castability is read off the spell's widget icon rather than stored here - see
 * {@link SpellIcon} - because which icon family the client draws from is a player display setting,
 * not something a spell-by-spell sprite id could ever pin down.
 */
public enum RoomSpell {
    TELEKINETIC_GRAB("Telekinetic Grab", InterfaceID.MagicSpellbook.TELEGRAB, 0),
    BONES_TO_BANANAS("Bones to Bananas", InterfaceID.MagicSpellbook.BONES_BANANAS, 0),
    BONES_TO_PEACHES("Bones to Peaches", InterfaceID.MagicSpellbook.BONES_PEACHES,
        VarbitID.MAGICTRAINING_BONESPEACHES),
    LOW_ALCHEMY("Low Level Alchemy", InterfaceID.MagicSpellbook.LOW_ALCHEMY, 0),
    HIGH_ALCHEMY("High Level Alchemy", InterfaceID.MagicSpellbook.HIGH_ALCHEMY, 0),
    ENCHANT_1("Lvl-1 Enchant", InterfaceID.MagicSpellbook.ENCHANT_1, 0, 7),
    ENCHANT_2("Lvl-2 Enchant", InterfaceID.MagicSpellbook.ENCHANT_2, 0, 27),
    ENCHANT_3("Lvl-3 Enchant", InterfaceID.MagicSpellbook.ENCHANT_3, 0, 49),
    ENCHANT_4("Lvl-4 Enchant", InterfaceID.MagicSpellbook.ENCHANT_4, 0, 57),
    ENCHANT_5("Lvl-5 Enchant", InterfaceID.MagicSpellbook.ENCHANT_5, 0, 68),
    ENCHANT_6("Lvl-6 Enchant", InterfaceID.MagicSpellbook.ENCHANT_6, 0, 87),
    ENCHANT_7("Lvl-7 Enchant", InterfaceID.MagicSpellbook.ENCHANT_7, 0, 93);

    private final String displayName;
    private final int component;
    private final int unlockVarbit;
    private final int levelRequirement;

    /** Leaves the level requirement at 0. Use the longer form for a spell whose level we compare. */
    RoomSpell(String displayName, int component, int unlockVarbit) {
        this(displayName, component, unlockVarbit, 0);
    }

    RoomSpell(String displayName, int component, int unlockVarbit, int levelRequirement) {
        this.displayName = displayName;
        this.component = component;
        this.unlockVarbit = unlockVarbit;
        this.levelRequirement = levelRequirement;
    }

    public String displayName() { return displayName; }
    public int component() { return component; }

    /** Varbit gating the spell behind a reward purchase, or 0 when the spell needs no unlock. */
    public int unlockVarbit() { return unlockVarbit; }

    /**
     * The Magic level this spell needs, or 0 where the cache is the only source. Only the enchants
     * carry one, because picking the highest castable enchant happens before any spellbook read.
     * SpellbookReader still reads the live requirement for the warning itself.
     */
    public int levelRequirement() { return levelRequirement; }

    /**
     * The spell a room needs, or null where the room has no spell. Takes the config rather than each
     * room's setting in turn, so adding a room does not add a parameter here. The boosted Magic level
     * is passed in because the enchanting room's automatic choice depends on it.
     */
    public static RoomSpell forRoom(Room room, LazyBonesConfig config, int boostedMagic) {
        switch (room) {
            case TELEKINETIC:
                return TELEKINETIC_GRAB;
            case GRAVEYARD:
                return config.spell() == Spell.BONES_TO_BANANAS ? BONES_TO_BANANAS : BONES_TO_PEACHES;
            case ALCHEMY:
                return config.alchemySpell().roomSpell();
            case ENCHANTMENT:
                return config.enchantChoice().resolve(boostedMagic);
            default:
                return null;
        }
    }

    @Override
    public String toString() { return displayName; }
}

package com.lazybones;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ImageComponent;
import net.runelite.client.ui.overlay.components.LineComponent;

/**
 * Says why the room's spell cannot be cast, and whether the Mage Training Arena plugin is covering
 * its half. Shown from the moment you walk in rather than at the point you would cast - finding out
 * after filling an inventory is the whole problem.
 */
public class RoomStatusOverlay extends OverlayPanel {

    private static final Color WARNING = new Color(255, 80, 80);

    // Room and spell names vary a lot in length ("Bones to Peaches" vs "High Level Alchemy"), so the
    // panel sizes itself to whatever it is about to draw rather than clipping at a fixed width. The
    // margin covers the panel border plus some breathing room; the cap stops one long spell name from
    // stretching the panel across half the screen - anything wider than that wraps instead.
    private static final int WIDTH_MARGIN = 20;
    private static final int MAX_PANEL_WIDTH = 250;

    private final LazyBonesState state;
    private final LazyBonesConfig config;
    private final SpriteManager spriteManager;

    private int loadedSpriteId = -1;
    private BufferedImage icon;

    @Inject
    RoomStatusOverlay(LazyBonesState state, LazyBonesConfig config, SpriteManager spriteManager) {
        this.state = state;
        this.config = config;
        this.spriteManager = spriteManager;
        setPosition(OverlayPosition.TOP_CENTER);
    }

    @Override
    public Dimension render(Graphics2D g) {
        if (state.room() == Room.NONE) {
            return null;
        }

        SpellStatus status = state.spellStatus();
        String title = WarningCopy.spellTitle(status);
        String reason = WarningCopy.spellReason(status);
        String mta = config.warnMtaPlugin() ? WarningCopy.mtaLine(state.mtaWarning(), state.room()) : null;

        if (title == null && mta == null) {
            return null;
        }

        FontMetrics metrics = g.getFontMetrics();
        int[] lineWidths = {
            title == null ? 0 : metrics.stringWidth(title),
            reason == null ? 0 : metrics.stringWidth(reason),
            mta == null ? 0 : metrics.stringWidth(mta)
        };
        panelComponent.setPreferredSize(new Dimension(PanelWidth.fit(lineWidths, WIDTH_MARGIN, MAX_PANEL_WIDTH), 0));

        panelComponent.getChildren().clear();

        if (title != null) {
            ensureIcon(status.spriteId());
            if (icon != null) {
                panelComponent.getChildren().add(new ImageComponent(icon));
            }
            // A TitleComponent centers on its own preferred width but never wraps, so a long spell
            // name would run past the panel it is centered on. LineComponent wraps its left text
            // within the panel width, so the title moves here instead.
            panelComponent.getChildren().add(LineComponent.builder()
                .left(title)
                .leftColor(WARNING)
                .build());
            panelComponent.getChildren().add(LineComponent.builder()
                .left(reason)
                .build());
        }

        if (mta != null) {
            panelComponent.getChildren().add(LineComponent.builder()
                .left(mta)
                .leftColor(Color.YELLOW)
                .build());
        }

        return super.render(g);
    }

    private void ensureIcon(int spriteId) {
        if (spriteId <= 0 || spriteId == loadedSpriteId) {
            return;
        }
        loadedSpriteId = spriteId;
        icon = null;
        spriteManager.getSpriteAsync(spriteId, 0, img -> icon = Sprites.scale2x(img));
    }
}

package com.lazybones;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import net.runelite.api.coords.WorldPoint;

public final class SceneMath {
    private SceneMath() {}

    /** Indices of the n points nearest `from`, closest first. Ignores points on a different plane. */
    public static List<Integer> nearestIndices(WorldPoint from, List<WorldPoint> pts, int n) {
        List<Integer> idx = new ArrayList<>();
        for (int i = 0; i < pts.size(); i++) {
            if (pts.get(i).getPlane() == from.getPlane()) {
                idx.add(i);
            }
        }
        idx.sort(Comparator.comparingInt(i -> from.distanceTo(pts.get(i))));
        return new ArrayList<>(idx.subList(0, Math.min(n, idx.size())));
    }
}

