package com.lazybones;

public final class SpellAvailability {
    private SpellAvailability() {}

    /**
     * Why the spell can or cannot be cast. The causes are checked in the order a player would want
     * to hear them, and only one is reported.
     *
     * Runes are concluded rather than counted. Once the spellbook, the unlock and the level all
     * check out, the icon settles it: {@link SpellIcon} reads which block the widget's sprite id
     * falls in, and that already knows about elemental staves, charged tomes, the rune pouch and the
     * explorer's ring the way counting inventory runes never could.
     *
     * @param spellbookVarbit current spellbook; 0 is the standard book
     * @param unlocked        false only for a spell behind a reward purchase the player lacks
     * @param boostedMagic    boosted Magic level, since a boost genuinely lets you cast
     * @param levelRequired   the spell's level requirement, or 0 if it could not be read
     * @param spriteId        the spell icon's sprite, or -1 when the widget is absent
     */
    public static Availability evaluate(RoomSpell spell, int spellbookVarbit, boolean unlocked,
                                        int boostedMagic, int levelRequired, int spriteId) {
        if (spellbookVarbit != 0) {
            return Availability.WRONG_SPELLBOOK;
        }
        if (!unlocked) {
            return Availability.NOT_UNLOCKED;
        }
        if (levelRequired > 0 && boostedMagic < levelRequired) {
            return Availability.LEVEL;
        }
        switch (SpellIcon.stateOf(spriteId)) {
            case CASTABLE:
                return Availability.AVAILABLE;
            case GREYED:
                return Availability.MISSING_RUNES;
            default:
                return Availability.UNKNOWN;
        }
    }
}

package com.lazybones;

/**
 * Classifies a spell icon by which block of the client's sprite sheet its id falls in, rather than by
 * a per-spell id. The spellbook draws icons from five parallel pairs of blocks (the classic 1x set,
 * plus four later additions including a 2x set), and which pair shows up for a given spell depends on
 * a client display setting the plugin has no way to read - so a table of "this spell's on sprite is
 * X" only ever matches players on the family that table was built from.
 *
 * That was the actual bug: in game, Lvl-5 Enchant showed sprite 1769 and High Level Alchemy showed
 * sprite 1781 while both were castable. Neither id matched either spell's hardcoded 1x sprite, because
 * the client was drawing from the 2x family instead - both ids land inside the ON range below.
 *
 * Ranges verified against runelite-api's SpriteID (Magicon/Magicoff, Magicon2/Magicoff2, and three
 * further pairs for later spellbook additions).
 */
public final class SpellIcon {
    private SpellIcon() {}

    private static final int[][] ON_RANGES = {
        {15, 64}, {319, 368}, {1732, 1811}, {6922, 6946}, {7479, 7503}
    };
    private static final int[][] OFF_RANGES = {
        {65, 114}, {369, 418}, {1812, 1891}, {6947, 6971}, {7504, 7528}
    };

    public enum State {
        CASTABLE,
        GREYED,
        UNKNOWN
    }

    public static State stateOf(int spriteId) {
        if (inAnyRange(ON_RANGES, spriteId)) {
            return State.CASTABLE;
        }
        if (inAnyRange(OFF_RANGES, spriteId)) {
            return State.GREYED;
        }
        return State.UNKNOWN;
    }

    private static boolean inAnyRange(int[][] ranges, int spriteId) {
        for (int[] range : ranges) {
            if (spriteId >= range[0] && spriteId <= range[1]) {
                return true;
            }
        }
        return false;
    }
}

