package com.lazybones;

import java.util.EnumMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.ItemComposition;
import net.runelite.api.ParamID;
import net.runelite.api.Skill;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;

/**
 * Reads a room spell's state from the live client.
 *
 * Level requirements come from the cache rather than a table in here, so they cannot drift out of
 * step with the game. The walk from varbit to spell object is the one the spellbook's own redraw
 * script uses.
 *
 * Every call reads Client state and must run on the client thread.
 */
@Singleton
public class SpellbookReader {

    private final Client client;
    private final Map<RoomSpell, Integer> levelCache = new EnumMap<>(RoomSpell.class);

    @Inject
    SpellbookReader(Client client) {
        this.client = client;
    }

    public SpellStatus status(RoomSpell spell) {
        int spellbook = client.getVarbitValue(VarbitID.SPELLBOOK);
        boolean unlocked = spell.unlockVarbit() == 0 || client.getVarbitValue(spell.unlockVarbit()) > 0;
        int magic = client.getBoostedSkillLevel(Skill.MAGIC);
        int levelRequired = levelRequirement(spell);

        Widget widget = client.getWidget(spell.component());
        int spriteId = widget == null ? -1 : widget.getSpriteId();

        Availability availability = SpellAvailability.evaluate(
            spell, spellbook, unlocked, magic, levelRequired, spriteId);
        return new SpellStatus(spell, availability, levelRequired, magic, spriteId);
    }

    /** @return the spell's level requirement, or 0 if the spellbook could not be walked this tick. */
    private int levelRequirement(RoomSpell spell) {
        Integer cached = levelCache.get(spell);
        if (cached != null) {
            return cached;
        }

        EnumComposition sub = client.getEnum(EnumID.SPELLBOOKS_SUB);
        if (sub == null) {
            return 0;
        }
        EnumComposition book = client.getEnum(sub.getIntValue(client.getVarbitValue(VarbitID.SPELLBOOK)));
        if (book == null) {
            return 0;
        }
        EnumComposition spells = client.getEnum(book.getIntValue(client.getVarbitValue(VarbitID.SPELLBOOK_SUBLIST)));
        if (spells == null) {
            return 0;
        }

        for (int i = 0; i < spells.size(); i++) {
            ItemComposition obj = client.getItemDefinition(spells.getIntValue(i));
            if (obj != null && obj.getIntValue(ParamID.SPELL_BUTTON) == spell.component()) {
                int level = obj.getIntValue(ParamID.SPELL_LEVELREQ);
                if (level > 0) {
                    // Only a real answer is cached; an empty read is retried next tick.
                    levelCache.put(spell, level);
                }
                return level;
            }
        }
        return 0;
    }
}

package com.lazybones;

import java.awt.Graphics2D;
import java.awt.image.BufferedImage;

final class Sprites {
    private Sprites() {}

    private static final int SCALE = 2;

    /** Spell icons are small; doubling them keeps the panel readable. */
    static BufferedImage scale2x(BufferedImage src) {
        if (src == null) {
            return null;
        }
        BufferedImage out = new BufferedImage(src.getWidth() * SCALE, src.getHeight() * SCALE, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = out.createGraphics();
        g.drawImage(src, 0, 0, out.getWidth(), out.getHeight(), null);
        g.dispose();
        return out;
    }
}

package com.lazybones;

/** Wording for the two warnings, kept apart from the drawing so it can be asserted. */
public final class WarningCopy {
    private WarningCopy() {}

    /** @return the panel title, or null when the spell is castable. */
    public static String spellTitle(SpellStatus status) {
        if (status == null || status.castable()) {
            return null;
        }
        return "Can't cast " + status.spell().displayName();
    }

    /** @return one line saying why the spell cannot be cast, or null when it can. */
    public static String spellReason(SpellStatus status) {
        if (status == null) {
            return null;
        }
        switch (status.availability()) {
            case AVAILABLE:
                return null;
            case WRONG_SPELLBOOK:
                return "Switch to the standard spellbook";
            case NOT_UNLOCKED:
                return "Buy " + status.spell().displayName() + " from the Rewards Guardian";
            case LEVEL:
                return "Needs Magic level " + status.levelRequired() + " - you have " + status.magicLevel();
            case MISSING_RUNES:
                return "Out of runes for " + status.spell().displayName();
            default:
                return "Open the Magic tab";
        }
    }

    /** @return one line about the arena plugin, or null when it is covering this room. */
    public static String mtaLine(MtaWarning warning, Room room) {
        switch (warning) {
            case PLUGIN_OFF:
                return "Mage Training Arena plugin is off - LazyBones leaves its highlights to it";
            case ROOM_OFF:
                return "Mage Training Arena plugin has " + room.displayName() + " switched off";
            default:
                return null;
        }
    }
}

package com.lazybones.alchemy;

import net.runelite.api.gameval.ObjectID;

/**
 * The six cupboards. Each has a separate id for its open and closed state, which is what makes a
 * rotation visible: since the cupboards stand open, one closing means the items are being swapped.
 */
public final class AlchemyIds {
    private AlchemyIds() {}

    private static final int[] OPEN = {
        ObjectID.MAGICTRAINING_ALCHEM_CUPBOARD0_OPEN,
        ObjectID.MAGICTRAINING_ALCHEM_CUPBOARD1_OPEN,
        ObjectID.MAGICTRAINING_ALCHEM_CUPBOARD2_OPEN,
        ObjectID.MAGICTRAINING_ALCHEM_CUPBOARD3_OPEN,
        ObjectID.MAGICTRAINING_ALCHEM_CUPBOARD4_OPEN,
        ObjectID.MAGICTRAINING_ALCHEM_CUPBOARD5_OPEN,
    };

    private static final int[] CLOSED = {
        ObjectID.MAGICTRAINING_ALCHEM_CUPBOARD0,
        ObjectID.MAGICTRAINING_ALCHEM_CUPBOARD1,
        ObjectID.MAGICTRAINING_ALCHEM_CUPBOARD2,
        ObjectID.MAGICTRAINING_ALCHEM_CUPBOARD3,
        ObjectID.MAGICTRAINING_ALCHEM_CUPBOARD4,
        ObjectID.MAGICTRAINING_ALCHEM_CUPBOARD5,
    };

    /** @return 0-5 for either state of a cupboard, or -1 for anything else. */
    public static int cupboardIndex(int objectId) {
        for (int i = 0; i < OPEN.length; i++) {
            if (objectId == OPEN[i] || objectId == CLOSED[i]) {
                return i;
            }
        }
        return -1;
    }

    public static boolean isClosed(int objectId) {
        for (int id : CLOSED) {
            if (objectId == id) {
                return true;
            }
        }
        return false;
    }
}

package com.lazybones.alchemy;

import net.runelite.api.gameval.ItemID;

/**
 * The six things a cupboard can hold, in the order they rotate. The order is what makes one search
 * enough: find any item and the other five follow from it.
 *
 * Matching is on a distinctive keyword rather than the full name. The chat line and the interface
 * row are not guaranteed to word an item the same way - the arena plugin shortens the helm to
 * "Helm" for exactly this reason - and a keyword survives either wording.
 */
public enum AlchemyItem {
    LEATHER_BOOTS("Leather boots", ItemID.MAGICTRAINING_LEATHER_BOOTS, "boots"),
    ADAMANT_KITESHIELD("Adamant kiteshield", ItemID.MAGICTRAINING_ADAMANT_KITESHIELD, "kite"),
    ADAMANT_MED_HELM("Adamant med helm", ItemID.MAGICTRAINING_ADAMANT_MED_HELM, "helm"),
    EMERALD("Emerald", ItemID.MAGICTRAINING_EMERALD, "emerald"),
    RUNE_LONGSWORD("Rune longsword", ItemID.MAGICTRAINING_RUNE_LONGSWORD, "sword"),
    EMPTY("Empty", -1, "empty");

    private final String displayName;
    private final int itemId;
    private final String keyword;

    AlchemyItem(String displayName, int itemId, String keyword) {
        this.displayName = displayName;
        this.itemId = itemId;
        this.keyword = keyword;
    }

    public String displayName() { return displayName; }

    /** Inventory item id, or -1 for {@link #EMPTY}. */
    public int itemId() { return itemId; }

    /** @return the item the text names, or null if it names none of them. */
    public static AlchemyItem fromText(String text) {
        if (text == null) {
            return null;
        }
        String lower = text.toLowerCase().replace(" ", "");
        for (AlchemyItem item : values()) {
            if (lower.contains(item.keyword)) {
                return item;
            }
        }
        return null;
    }

    @Override
    public String toString() { return displayName; }
}

package com.lazybones.alchemy;

/**
 * Which cupboard holds which item. Positions rotate every 60 seconds but the sequence never does,
 * so one confirmed sighting fixes all six.
 */
public final class CupboardMap {

    public static final int CUPBOARDS = 6;

    private final AlchemyItem[] byCupboard = new AlchemyItem[CUPBOARDS];
    private boolean solved;

    /** Record that the given cupboard holds the given item, and derive the rest from the order. */
    public void solve(int cupboard, AlchemyItem found) {
        if (cupboard < 0 || cupboard >= CUPBOARDS || found == null) {
            return;
        }
        AlchemyItem[] order = AlchemyItem.values();
        for (int i = 0; i < CUPBOARDS; i++) {
            byCupboard[(cupboard + i) % CUPBOARDS] = order[(found.ordinal() + i) % CUPBOARDS];
        }
        solved = true;
    }

    /** The items have rotated; what we knew is now wrong. */
    public void invalidate() {
        for (int i = 0; i < CUPBOARDS; i++) {
            byCupboard[i] = null;
        }
        solved = false;
    }

    public boolean solved() { return solved; }

    /** @return the cupboard index holding the item, or -1 while unsolved. */
    public int cupboardFor(AlchemyItem item) {
        if (!solved || item == null) {
            return -1;
        }
        for (int i = 0; i < CUPBOARDS; i++) {
            if (byCupboard[i] == item) {
                return i;
            }
        }
        return -1;
    }
}

package com.lazybones.alchemy;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

/**
 * Which items are free to convert right now, read off the green arrows in the room's value table.
 *
 * The Alchemy Guardian shouts the same thing, but only within earshot, so the table is the better
 * source: it is correct the moment the values change and does not care where the player stands.
 *
 * Reads Client state and must run on the client thread.
 */
@Singleton
public class FreeItemReader {

    private static final int[] ARROWS = {
        InterfaceID.MagictrainingAlchem.MAGICTRAIN_ARROW1,
        InterfaceID.MagictrainingAlchem.MAGICTRAIN_ARROW2,
        InterfaceID.MagictrainingAlchem.MAGICTRAIN_ARROW3,
        InterfaceID.MagictrainingAlchem.MAGICTRAIN_ARROW4,
        InterfaceID.MagictrainingAlchem.MAGICTRAIN_ARROW5,
    };

    private static final int[] ITEMS = {
        InterfaceID.MagictrainingAlchem.MAGICTRAIN_ALCHEM_ITEM1,
        InterfaceID.MagictrainingAlchem.MAGICTRAIN_ALCHEM_ITEM2,
        InterfaceID.MagictrainingAlchem.MAGICTRAIN_ALCHEM_ITEM3,
        InterfaceID.MagictrainingAlchem.MAGICTRAIN_ALCHEM_ITEM4,
        InterfaceID.MagictrainingAlchem.MAGICTRAIN_ALCHEM_ITEM5,
    };

    private final Client client;

    @Inject
    FreeItemReader(Client client) {
        this.client = client;
    }

    /** @return the free items, empty when none is. Never null. */
    public List<AlchemyItem> freeItems() {
        List<AlchemyItem> free = new ArrayList<>();
        for (int row = 0; row < ARROWS.length; row++) {
            Widget arrow = client.getWidget(ARROWS[row]);
            if (arrow == null || arrow.isHidden()) {
                continue;
            }
            Widget name = client.getWidget(ITEMS[row]);
            if (name == null) {
                continue;
            }
            AlchemyItem item = AlchemyItem.fromText(name.getText());
            if (item != null && item != AlchemyItem.EMPTY) {
                free.add(item);
            }
        }
        return free.isEmpty() ? Collections.emptyList() : free;
    }
}

package com.lazybones.enchant;

/**
 * The current bonus shape, and the tick its window began.
 *
 * Walking in tells you the shape but not how long it has been up, so the timing stays unknown until
 * the first change is seen. Everything that does not need the clock works from the first tick.
 */
public class BonusShapeTracker {

    private Shape shape;
    private int windowStartTick;
    private boolean known;

    /** Feed the observed shape and the current tick. A null observation is ignored. */
    public void observe(Shape read, int tick) {
        if (read == null) {
            return;
        }
        if (shape != null && read != shape) {
            windowStartTick = tick;
            known = true;
        }
        shape = read;
    }

    public Shape shape() { return shape; }

    /** Whether the window start has been seen. False until the shape changes once. */
    public boolean known() { return known; }

    /** Ticks since the window began, or 0 until {@link #known()} - there is nothing to count from. */
    public int elapsedTicks(int nowTick) {
        return known ? nowTick - windowStartTick : 0;
    }

    public void clear() {
        shape = null;
        windowStartTick = 0;
        known = false;
    }
}

package com.lazybones.enchant;

public final class PickupCalculator {
    private PickupCalculator() {}

    /**
     * Ticks left in the current window.
     *
     * Elapsed time wraps rather than clamping. A window can end without the indicator text changing -
     * if the same shape comes up twice in a row there is nothing to see - and clamping would leave the
     * bar full and the count at zero until the player left the room. Wrapping keeps both moving, and
     * the next change the tracker does see re-anchors the timing exactly.
     *
     * The window length itself was timed in game across eight consecutive shape changes and came out
     * to exactly 40 ticks every time, so the config default is correct as it stands.
     */
    public static int ticksLeft(int elapsedTicks, TickModel model) {
        int window = model.windowTicks();
        int elapsed = elapsedTicks % window;
        if (elapsed < 0) {
            elapsed += window;
        }
        return window - elapsed;
    }

    /**
     * How many more shapes are worth taking from the pile.
     *
     * Counts what is already held, because those still have to be enchanted before the window closes:
     * the answer is "how many more", so it falls both as the clock runs down and as the hand fills,
     * and zero means stop and start casting.
     */
    public static int pickups(int ticksLeft, int heldShapes, TickModel model) {
        int reserved = Math.max(0, heldShapes) * model.enchantTicks();
        int available = ticksLeft - model.bufferTicks() - reserved;
        if (available <= 0) {
            return 0;
        }
        return available / model.cycleTicks();
    }
}

package com.lazybones.enchant;

import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.ObjectID;

/**
 * The four shapes, each with the ground item you carry and the pile you take it from.
 *
 * The pile ids are named by number rather than by shape and the item ids run in a different order,
 * so the pairing below cannot be derived - it is the one place it is written down, and the first
 * thing to check in game if a pile ever highlights for the wrong shape.
 */
public enum Shape {
    CUBE("Cube", ItemID.MAGICTRAINING_ENCHAN_CUBE, ObjectID.MAGICTRAINING_ENCHAN_SHAPEPILE1),
    CYLINDER("Cylinder", ItemID.MAGICTRAINING_ENCHAN_CYLINDER, ObjectID.MAGICTRAINING_ENCHAN_SHAPEPILE2),
    ICOSAHEDRON("Icosahedron", ItemID.MAGICTRAINING_ENCHAN_ICOSAHENDRON, ObjectID.MAGICTRAINING_ENCHAN_SHAPEPILE3),
    PENTAMID("Pentamid", ItemID.MAGICTRAINING_ENCHAN_PENTAMID, ObjectID.MAGICTRAINING_ENCHAN_SHAPEPILE4);

    private final String displayName;
    private final int itemId;
    private final int pileObjectId;

    Shape(String displayName, int itemId, int pileObjectId) {
        this.displayName = displayName;
        this.itemId = itemId;
        this.pileObjectId = pileObjectId;
    }

    public String displayName() { return displayName; }
    public int itemId() { return itemId; }
    public int pileObjectId() { return pileObjectId; }

    /** @return the shape whose pile this is, or null for any other object. */
    public static Shape fromPileObjectId(int objectId) {
        for (Shape shape : values()) {
            if (shape.pileObjectId == objectId) {
                return shape;
            }
        }
        return null;
    }

    @Override
    public String toString() { return displayName; }
}

package com.lazybones.enchant;

/**
 * How long the room's actions take, in game ticks. Every number is a setting rather than a constant:
 * the window length and the cost of an enchant are known only from play, so they can be corrected
 * without a new build.
 */
public final class TickModel {

    private final int windowTicks;
    private final int enchantTicks;
    private final int pickupTicks;
    private final int bufferTicks;

    public TickModel(int windowTicks, int enchantTicks, int pickupTicks, int bufferTicks) {
        // A window of zero would divide by nothing downstream, and negative costs are meaningless.
        this.windowTicks = Math.max(1, windowTicks);
        this.enchantTicks = Math.max(0, enchantTicks);
        this.pickupTicks = Math.max(0, pickupTicks);
        this.bufferTicks = Math.max(0, bufferTicks);
    }

    public int windowTicks() { return windowTicks; }
    public int enchantTicks() { return enchantTicks; }
    public int pickupTicks() { return pickupTicks; }
    public int bufferTicks() { return bufferTicks; }

    /** Ticks spent on one shape, start to finish. At least 1, so the pickup count cannot diverge. */
    public int cycleTicks() {
        return Math.max(1, pickupTicks + enchantTicks);
    }
}

package com.lazybones;

import com.lazybones.alchemy.AlchemyItem;
import com.lazybones.alchemy.FreeItemReader;
import java.util.Collections;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.ObjectID;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class AlchemyRoomTest {

    @Mock private Client client;
    @Mock private LazyBonesConfig config;
    @Mock private FreeItemReader freeItemReader;
    @Mock private GameObject cupboard0;
    @Mock private GameObject cupboard3;
    @Mock private Player localPlayer;

    private LazyBonesState state;
    private AlchemyRoom room;

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
        state = new LazyBonesState();
        room = new AlchemyRoom(client, config, state, freeItemReader);

        when(config.showFreeItems()).thenReturn(true);
        when(freeItemReader.freeItems()).thenReturn(Collections.emptyList());
        when(cupboard0.getId()).thenReturn(ObjectID.MAGICTRAINING_ALCHEM_CUPBOARD0_OPEN);
        when(cupboard0.getWorldLocation()).thenReturn(new WorldPoint(3360, 9630, 2));
        when(cupboard3.getId()).thenReturn(ObjectID.MAGICTRAINING_ALCHEM_CUPBOARD3_OPEN);
        when(cupboard3.getWorldLocation()).thenReturn(new WorldPoint(3364, 9630, 2));
        // The chat line names the item, not the cupboard - onChatMessage falls back to whichever
        // cupboard the player is standing nearest, same as GraveyardRoomTest's chute lookup.
        when(localPlayer.getWorldLocation()).thenReturn(new WorldPoint(3360, 9630, 2));
        when(client.getLocalPlayer()).thenReturn(localPlayer);
    }

    @Test
    public void reportsTheGraveyardsSiblingRoom() {
        assertEquals(Room.ALCHEMY, room.room());
    }

    @Test
    public void marksNothingUntilAFreeItemAppears() {
        room.onGameObjectSpawned(cupboard0);
        room.onChatMessage("You found: Leather boots");
        room.onTick();
        assertTrue(state.freeCupboards().isEmpty());
        assertTrue(state.freeItemIds().isEmpty());
    }

    @Test
    public void marksTheInventoryEvenBeforeAnyCupboardIsSearched() {
        // The value table names the free item straight away; only its cupboard needs a search.
        when(freeItemReader.freeItems()).thenReturn(Collections.singletonList(AlchemyItem.EMERALD));
        room.onTick();
        assertEquals(Collections.singleton(AlchemyItem.EMERALD.itemId()), state.freeItemIds());
        assertTrue(state.freeCupboards().isEmpty());
    }

    @Test
    public void marksTheCupboardOnceTheRotationIsSolved() {
        room.onGameObjectSpawned(cupboard0);
        room.onGameObjectSpawned(cupboard3);
        room.onChatMessage("You found: Leather boots");
        // Boots in cupboard 0 puts the emerald three along, in cupboard 3.
        when(freeItemReader.freeItems()).thenReturn(Collections.singletonList(AlchemyItem.EMERALD));
        room.onTick();
        assertEquals(Collections.singletonList(cupboard3), state.freeCupboards());
    }

    @Test
    public void aClickedCupboardTakesPriorityOverTheNearest() {
        room.onGameObjectSpawned(cupboard0);
        room.onGameObjectSpawned(cupboard3);
        // setUp stands the player right on top of cupboard0, so nearestCupboard() would pick it -
        // the click on cupboard 3 has to win over that fallback.
        room.onCupboardClicked(3);
        room.onChatMessage("You found: Leather boots");
        when(freeItemReader.freeItems()).thenReturn(Collections.singletonList(AlchemyItem.LEATHER_BOOTS));
        room.onTick();
        assertEquals(Collections.singletonList(cupboard3), state.freeCupboards());
    }

    @Test
    public void aCupboardClosingForgetsTheRotation() {
        room.onGameObjectSpawned(cupboard0);
        room.onChatMessage("You found: Leather boots");
        when(freeItemReader.freeItems()).thenReturn(Collections.singletonList(AlchemyItem.LEATHER_BOOTS));
        room.onTick();
        assertEquals(Collections.singletonList(cupboard0), state.freeCupboards());

        GameObject closing = org.mockito.Mockito.mock(GameObject.class);
        when(closing.getId()).thenReturn(ObjectID.MAGICTRAINING_ALCHEM_CUPBOARD0);
        when(closing.getWorldLocation()).thenReturn(new WorldPoint(3360, 9630, 2));
        room.onGameObjectSpawned(closing);
        room.onTick();
        assertTrue("a rotation must drop the old mapping", state.freeCupboards().isEmpty());
    }

    @Test
    public void theSettingSilencesTheMarking() {
        when(config.showFreeItems()).thenReturn(false);
        room.onGameObjectSpawned(cupboard0);
        room.onChatMessage("You found: Leather boots");
        when(freeItemReader.freeItems()).thenReturn(Collections.singletonList(AlchemyItem.LEATHER_BOOTS));
        room.onTick();
        assertTrue(state.freeCupboards().isEmpty());
        assertTrue(state.freeItemIds().isEmpty());
    }

    @Test
    public void standDownStopsMarking() {
        when(freeItemReader.freeItems()).thenReturn(Collections.singletonList(AlchemyItem.EMERALD));
        room.onTick();
        room.standDown();
        assertTrue(state.freeCupboards().isEmpty());
        assertTrue(state.freeItemIds().isEmpty());
    }

    @Test
    public void standDownClearsAResolvedCupboard() {
        room.onGameObjectSpawned(cupboard0);
        room.onGameObjectSpawned(cupboard3);
        room.onChatMessage("You found: Leather boots");
        // Boots in cupboard 0 puts the emerald three along, in cupboard 3.
        when(freeItemReader.freeItems()).thenReturn(Collections.singletonList(AlchemyItem.EMERALD));
        room.onTick();
        assertEquals(Collections.singletonList(cupboard3), state.freeCupboards());

        room.standDown();
        assertTrue(state.freeCupboards().isEmpty());
        assertTrue(state.freeItemIds().isEmpty());
    }

    @Test
    public void aSceneReloadDropsTheStaleMapping() {
        room.onGameObjectSpawned(cupboard0);
        room.onGameObjectSpawned(cupboard3);
        room.onChatMessage("You found: Leather boots");
        // Boots in cupboard 0 puts the emerald three along, in cupboard 3.
        when(freeItemReader.freeItems()).thenReturn(Collections.singletonList(AlchemyItem.EMERALD));
        room.onTick();
        assertEquals(Collections.singletonList(cupboard3), state.freeCupboards());

        room.onSceneLoading();
        room.onTick();
        // Leaving the arena reloads the scene; the solved rotation and the cupboard refs it
        // pointed at are gone, so there is nothing left to mark until a fresh search happens.
        assertTrue(state.freeCupboards().isEmpty());
        assertEquals(Collections.singleton(AlchemyItem.EMERALD.itemId()), state.freeItemIds());
    }

    @Test
    public void neverTouchesTheHintArrow() {
        // The arena plugin owns the client's single hint arrow in this room. Taking it, or clearing
        // it, moves that plugin's marker off the 30-point cupboard.
        room.onGameObjectSpawned(cupboard0);
        room.onChatMessage("You found: Leather boots");
        when(freeItemReader.freeItems()).thenReturn(Collections.singletonList(AlchemyItem.LEATHER_BOOTS));
        room.onTick();
        room.standDown();
        room.reset();
        verify(client, never()).setHintArrow(org.mockito.ArgumentMatchers.any(WorldPoint.class));
        verify(client, never()).clearHintArrow();
    }
}

package com.lazybones;

import org.junit.Test;
import static org.junit.Assert.assertEquals;

public class ClickCalculatorTest {
    @Test
    public void peachesWorkedExampleMatchesWiki() {
        // capacity 26 -> target 24; pile currently value 3, fresh (0 taken).
        // 4x3 = 12, then flips to value 4: 3x4 = 12 -> 24 at 7 clicks.
        assertEquals(7, ClickCalculator.clicksToTarget(0, 26, Spell.BONES_TO_PEACHES, 3, 0));
    }

    @Test
    public void alreadyAtTargetIsZeroClicks() {
        assertEquals(0, ClickCalculator.clicksToTarget(24, 28, Spell.BONES_TO_PEACHES, 2, 0));
        assertEquals(0, ClickCalculator.clicksToTarget(28, 28, Spell.BONES_TO_BANANAS, 1, 0));
    }

    @Test
    public void bananasFillFromValueTwoPile() {
        // capacity 28 -> target 28; a value-2 pile lands exactly on 28: 2,4,6,8(->3),11,14,17,20(->4),24,28 = 10.
        assertEquals(10, ClickCalculator.clicksToTarget(0, 28, Spell.BONES_TO_BANANAS, 2, 0));
    }

    @Test
    public void bananasStopShortRatherThanOverfill() {
        // capacity 27 (a rune pouch in slot 1); value-4 pile. 4,4,4,4,1,1,1,1,2,2,2 reaches 26 at 11 clicks;
        // a 12th click (value 2) would hit 28 > 27, so it stops at 26 - fills without spilling.
        assertEquals(11, ClickCalculator.clicksToTarget(0, 27, Spell.BONES_TO_BANANAS, 4, 0));
    }

    @Test
    public void bananasPileShowsZeroWhenNextClickWouldOverfill() {
        // held 26, capacity 27, value-4 pile: the next bone would hit 30, so this pile must not be clicked.
        assertEquals(0, ClickCalculator.clicksToTarget(26, 27, Spell.BONES_TO_BANANAS, 4, 0));
    }

    @Test
    public void bananasValueOnePileTopsOffToExactlyFull() {
        // held 26, capacity 27, value-1 pile: one click lands exactly on 27.
        assertEquals(1, ClickCalculator.clicksToTarget(26, 27, Spell.BONES_TO_BANANAS, 1, 0));
    }

    @Test
    public void bananasStillStopBeforeOverfilling() {
        // held 23, capacity 24, value-2 pile: 23 + 2 = 25 > 24, so it shows 0. Bananas never overfill.
        assertEquals(0, ClickCalculator.clicksToTarget(23, 24, Spell.BONES_TO_BANANAS, 2, 0));
    }

    @Test
    public void peachesTakeTheHitPastCapacityToReachTwentyFour() {
        // Same inputs on peaches: held 23, capacity 24, value-2 pile. One click reaches 25 - over 24 and over
        // capacity - but peaches take it anyway. You still get 24 peaches; the spill costs no points.
        assertEquals(1, ClickCalculator.clicksToTarget(23, 24, Spell.BONES_TO_PEACHES, 2, 0));
    }

    @Test
    public void respectsPartialTypeProgress() {
        // value-1 pile, 3 already taken: only 1 value-1 left, then it flips to 2,2,2,2,3...
        // held 0, target 10 (peaches, low capacity): 1,2,2,2,2,3 crosses 10 at 6 clicks (reaching 12).
        // Ignoring the 3-already-taken (1,1,1,1,2,2,2 -> lands on 10) would give 7, so this discriminates.
        assertEquals(6, ClickCalculator.clicksToTarget(0, 10, Spell.BONES_TO_PEACHES, 1, 3));
    }

    @Test
    public void peachesReachTargetEvenWhenItOvershoots() {
        // capacity 10 -> target 10 (peaches); value-2 pile: 2,4,6,8 (flips to 3), 11 -> crosses 10 at 5 clicks.
        // Peaches may overshoot, so they do not stop short of the target the way bananas would.
        assertEquals(5, ClickCalculator.clicksToTarget(0, 10, Spell.BONES_TO_PEACHES, 2, 0));
    }

    @Test
    public void cyclesFromValueFourWrappingToOne() {
        // pile value 4 fresh: 4,4,4,4 (wraps 4->1), 1,1,1,1 (wraps 1->2), 2,2 -> reaches 24 at 10 clicks.
        assertEquals(10, ClickCalculator.clicksToTarget(0, 28, Spell.BONES_TO_PEACHES, 4, 0));
    }

    @Test
    public void countsFromNonZeroHeldValue() {
        // already holding 20; target 24; pile value 2 -> two more clicks (22, 24).
        assertEquals(2, ClickCalculator.clicksToTarget(20, 28, Spell.BONES_TO_PEACHES, 2, 0));
    }
}

package com.lazybones;

import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.TreeSet;
import net.runelite.client.config.ConfigItem;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

// Structural invariants for the config panel: keyNames unique, item positions unique and contiguous
// from zero, and every enum-typed config item returns a public enum (package-private ones throw
// IllegalAccessError at runtime). A dropped item or a gapped/duplicate position fails here.
public class ConfigIntegrityTest {

    @Test
    public void configItemKeyNamesAreUnique() {
        Set<String> seen = new HashSet<>();
        for (Method m : LazyBonesConfig.class.getMethods()) {
            ConfigItem ci = m.getAnnotation(ConfigItem.class);
            if (ci != null) {
                assertTrue("duplicate keyName: " + ci.keyName(), seen.add(ci.keyName()));
            }
        }
        // Non-vacuity guard: reflection must actually find the items, else the checks pass over nothing.
        assertTrue("expected the config's @ConfigItem methods; found " + seen.size(), seen.size() >= 4);
    }

    @Test
    public void itemPositionsAreUniqueAndContiguousFromZero() {
        List<Integer> positions = new ArrayList<>();
        for (Method m : LazyBonesConfig.class.getMethods()) {
            ConfigItem ci = m.getAnnotation(ConfigItem.class);
            if (ci != null) {
                positions.add(ci.position());
            }
        }
        assertTrue("expected @ConfigItem methods; found " + positions.size(), positions.size() >= 4);
        Set<Integer> unique = new TreeSet<>(positions);
        assertEquals("duplicate positions: " + positions, positions.size(), unique.size());
        int expected = 0;
        for (int p : unique) {
            assertEquals("positions not contiguous from 0: " + unique, expected, p);
            expected++;
        }
    }

    @Test
    public void enumReturnTypesArePublic() {
        for (Method m : LazyBonesConfig.class.getMethods()) {
            Class<?> rt = m.getReturnType();
            if (rt.isEnum()) {
                assertTrue(rt.getName() + " must be public", Modifier.isPublic(rt.getModifiers()));
            }
        }
    }

    @Test
    public void legacyKeyNamesArePreserved() {
        Set<String> keys = new HashSet<>();
        for (Method m : LazyBonesConfig.class.getMethods()) {
            ConfigItem ci = m.getAnnotation(ConfigItem.class);
            if (ci != null) {
                keys.add(ci.keyName());
            }
        }
        // Renaming any of these discards the user's existing setting on upgrade.
        String[] shipped = {
            "warnMtaPlugin", "roomGraveyard", "roomTelekinetic", "roomAlchemy", "roomEnchanting",
            "spell", "showNumbers", "highlightColor", "showDepositArrow",
            "alchemySpell", "showFreeItems", "freeItemColor",
            "enchantChoice", "highlightDragonstones", "showBonusBar", "showPickupCount",
            "bufferTicks", "enchantTicks", "pickupTicks", "windowTicks",
            "dragonstoneColor", "bonusPileColor",
        };
        for (String key : shipped) {
            assertTrue("lost keyName: " + key, keys.contains(key));
        }
        assertTrue("expected the config's @ConfigItem methods; found " + keys.size(),
            keys.size() >= shipped.length);
    }

    @Test
    public void everyItemDeclaresASection() {
        int checked = 0;
        for (Method m : LazyBonesConfig.class.getMethods()) {
            ConfigItem ci = m.getAnnotation(ConfigItem.class);
            if (ci != null) {
                assertTrue(ci.keyName() + " has no section", !ci.section().isEmpty());
                checked++;
            }
        }
        assertTrue("expected the config's @ConfigItem methods; found " + checked, checked >= 7);
    }
}

package com.lazybones;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

public class EnchantChoiceTest {

    @Test
    public void autoTakesTheHighestYouCanCast() {
        // Each tier is checked at its requirement and one level below it. Without the level below,
        // a requirement written one too low would still satisfy every assertion here.
        assertEquals(RoomSpell.ENCHANT_1, EnchantChoice.AUTO.resolve(7));
        assertEquals(RoomSpell.ENCHANT_1, EnchantChoice.AUTO.resolve(26));
        assertEquals(RoomSpell.ENCHANT_2, EnchantChoice.AUTO.resolve(27));
        assertEquals(RoomSpell.ENCHANT_2, EnchantChoice.AUTO.resolve(48));
        assertEquals(RoomSpell.ENCHANT_3, EnchantChoice.AUTO.resolve(49));
        assertEquals(RoomSpell.ENCHANT_3, EnchantChoice.AUTO.resolve(56));
        assertEquals(RoomSpell.ENCHANT_4, EnchantChoice.AUTO.resolve(57));
        assertEquals(RoomSpell.ENCHANT_4, EnchantChoice.AUTO.resolve(67));
        assertEquals(RoomSpell.ENCHANT_5, EnchantChoice.AUTO.resolve(68));
        assertEquals(RoomSpell.ENCHANT_5, EnchantChoice.AUTO.resolve(86));
        assertEquals(RoomSpell.ENCHANT_6, EnchantChoice.AUTO.resolve(87));
    }

    @Test
    public void autoStopsAtSixEvenAtNinetyNine() {
        // Lvl-7 costs far more runes for one more point, so auto never picks it.
        assertEquals(RoomSpell.ENCHANT_6, EnchantChoice.AUTO.resolve(93));
        assertEquals(RoomSpell.ENCHANT_6, EnchantChoice.AUTO.resolve(99));
    }

    @Test
    public void autoBelowTheFirstRequirementStillNamesLevelOne() {
        // Nothing is castable yet, so name the cheapest and let the warning say why it is greyed.
        assertEquals(RoomSpell.ENCHANT_1, EnchantChoice.AUTO.resolve(1));
        assertEquals(RoomSpell.ENCHANT_1, EnchantChoice.AUTO.resolve(0));
    }

    @Test
    public void anOverrideIgnoresYourLevel() {
        assertEquals(RoomSpell.ENCHANT_5, EnchantChoice.LVL_5.resolve(1));
        assertEquals(RoomSpell.ENCHANT_1, EnchantChoice.LVL_1.resolve(99));
    }

    @Test
    public void sevenIsAvailableOnlyByAsking() {
        assertEquals(RoomSpell.ENCHANT_7, EnchantChoice.LVL_7.resolve(99));
    }

    @Test
    public void everyChoiceResolvesToSomething() {
        for (EnchantChoice choice : EnchantChoice.values()) {
            assertNotNull(choice + " resolves to nothing", choice.resolve(70));
        }
    }

    @Test
    public void theEnchantsAreOrderedByRequirement() {
        RoomSpell[] enchants = {
            RoomSpell.ENCHANT_1, RoomSpell.ENCHANT_2, RoomSpell.ENCHANT_3,
            RoomSpell.ENCHANT_4, RoomSpell.ENCHANT_5, RoomSpell.ENCHANT_6, RoomSpell.ENCHANT_7,
        };
        for (int i = 1; i < enchants.length; i++) {
            assertEquals(enchants[i] + " must need more than " + enchants[i - 1], true,
                enchants[i].levelRequirement() > enchants[i - 1].levelRequirement());
        }
    }
}

package com.lazybones;

import com.lazybones.enchant.Shape;
import java.util.Collections;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.Tile;
import net.runelite.api.TileItem;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class EnchantingRoomTest {

    @Mock private Client client;
    @Mock private LazyBonesConfig config;
    @Mock private Widget bonusWidget;
    @Mock private Widget cubeModel;
    @Mock private Widget cylinderModel;
    @Mock private Widget pentamidModel;
    @Mock private Widget icosahedronModel;
    @Mock private GameObject cubePile;
    @Mock private ItemContainer inventory;
    @Mock private Player player;

    private LazyBonesState state;
    private EnchantingRoom room;
    private int tick;

    private static final WorldPoint PLAYER_AT = new WorldPoint(3360, 9630, 0);
    private static final WorldPoint NEAR_PILE_AT = new WorldPoint(3362, 9630, 0);
    private static final WorldPoint FAR_PILE_AT = new WorldPoint(3390, 9630, 0);

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
        state = new LazyBonesState();
        room = new EnchantingRoom(client, config, state);

        when(config.showBonusBar()).thenReturn(true);
        when(config.showPickupCount()).thenReturn(true);
        when(config.windowTicks()).thenReturn(40);
        when(config.enchantTicks()).thenReturn(3);
        when(config.pickupTicks()).thenReturn(1);
        when(config.bufferTicks()).thenReturn(4);

        doReturn(null).when(client).getWidget(anyInt());
        doReturn(cubeModel).when(client).getWidget(InterfaceID.MagictrainingEncha.MAGICTRAIN_CUBE);
        doReturn(cylinderModel).when(client).getWidget(InterfaceID.MagictrainingEncha.MAGICTRAIN_CYLINDER);
        doReturn(pentamidModel).when(client).getWidget(InterfaceID.MagictrainingEncha.MAGICTRAIN_PENTAMID);
        doReturn(icosahedronModel).when(client).getWidget(InterfaceID.MagictrainingEncha.MAGICTRAIN_ICOSAHEDRON);
        showShape(Shape.CUBE);
        when(cubePile.getId()).thenReturn(Shape.CUBE.pileObjectId());
        when(cubePile.getWorldLocation()).thenReturn(PLAYER_AT);

        when(client.getLocalPlayer()).thenReturn(player);
        when(player.getWorldLocation()).thenReturn(PLAYER_AT);

        when(client.getItemContainer(InventoryID.INV)).thenReturn(inventory);
        when(inventory.getItems()).thenReturn(new Item[0]);

        tick = 100;
        when(client.getTickCount()).thenAnswer(invocation -> tick);
    }

    private void tickTo(int newTick) {
        tick = newTick;
        room.onTick();
    }

    /** Unhides the one model widget for the given shape and hides the rest. Null hides all four. */
    private void showShape(Shape shape) {
        when(cubeModel.isHidden()).thenReturn(shape != Shape.CUBE);
        when(cylinderModel.isHidden()).thenReturn(shape != Shape.CYLINDER);
        when(pentamidModel.isHidden()).thenReturn(shape != Shape.PENTAMID);
        when(icosahedronModel.isHidden()).thenReturn(shape != Shape.ICOSAHEDRON);
    }

    @Test
    public void reportsItsRoom() {
        assertEquals(Room.ENCHANTMENT, room.room());
    }

    @Test
    public void readsTheBonusShapeStraightAway() {
        room.onTick();
        assertNotNull(state.enchantView());
        assertEquals(Shape.CUBE, state.enchantView().shape());
    }

    @Test
    public void theShapeComesFromTheVisibleModelNotTheBonusText() {
        // MAGICTRAIN_ENCH_BONUSTXT is a static label - the smoke run showed it always reads "Bonus:",
        // never a shape name. If the shape were still parsed from it, this would see no shape at all.
        doReturn(bonusWidget).when(client).getWidget(InterfaceID.MagictrainingEncha.MAGICTRAIN_ENCH_BONUSTXT);
        when(bonusWidget.getText()).thenReturn("Bonus:");
        showShape(Shape.CYLINDER);

        room.onTick();
        assertEquals(Shape.CYLINDER, state.enchantView().shape());
    }

    @Test
    public void theTimingIsUnknownUntilTheShapeChanges() {
        room.onTick();
        assertEquals(false, state.enchantView().timingKnown());
        showShape(Shape.CYLINDER);
        tickTo(130);
        assertEquals(true, state.enchantView().timingKnown());
    }

    @Test
    public void marksTheBonusShapesPile() {
        room.onGameObjectSpawned(cubePile);
        room.onTick();
        assertEquals(cubePile, state.enchantView().bonusPile());
    }

    @Test
    public void aDespawnedPileStopsBeingMarked() {
        room.onGameObjectSpawned(cubePile);
        room.onTick();
        assertNotNull(state.enchantView().bonusPile());

        room.onGameObjectDespawned(cubePile);
        room.onTick();
        assertNull(state.enchantView().bonusPile());
    }

    @Test
    public void aDespawnOfAReplacedPileLeavesTheLiveOneAlone() {
        // A respawn can arrive before the old object's despawn. Dropping the entry on any despawn of
        // that shape would then forget the pile we just started tracking.
        GameObject replacement = org.mockito.Mockito.mock(GameObject.class);
        when(replacement.getId()).thenReturn(Shape.CUBE.pileObjectId());
        when(replacement.getWorldLocation()).thenReturn(PLAYER_AT);

        room.onGameObjectSpawned(cubePile);
        room.onGameObjectSpawned(replacement);
        room.onGameObjectDespawned(cubePile);
        room.onTick();
        assertEquals(replacement, state.enchantView().bonusPile());
    }

    private GameObject pileAt(Shape shape, WorldPoint point) {
        GameObject object = org.mockito.Mockito.mock(GameObject.class);
        when(object.getId()).thenReturn(shape.pileObjectId());
        when(object.getWorldLocation()).thenReturn(point);
        return object;
    }

    @Test
    public void marksTheNearerPileOfTheBonusShape() {
        // Twenty-four piles of each shape are scattered round the room; the far one must not win just
        // because it spawned second.
        GameObject near = pileAt(Shape.CUBE, NEAR_PILE_AT);
        GameObject far = pileAt(Shape.CUBE, FAR_PILE_AT);
        room.onGameObjectSpawned(far);
        room.onGameObjectSpawned(near);

        room.onTick();
        assertEquals(near, state.enchantView().bonusPile());

        when(player.getWorldLocation()).thenReturn(FAR_PILE_AT);
        room.onTick();
        assertEquals("the mark follows the player, not the spawn order", far, state.enchantView().bonusPile());
    }

    @Test
    public void aNonBonusShapePileIsNeverMarkedEvenIfCloser() {
        GameObject wrongShapeNear = pileAt(Shape.CYLINDER, PLAYER_AT);
        GameObject bonusShapeFar = pileAt(Shape.CUBE, FAR_PILE_AT);
        room.onGameObjectSpawned(wrongShapeNear);
        room.onGameObjectSpawned(bonusShapeFar);

        room.onTick();
        assertEquals("the closer pile is the wrong shape, so it must not be marked",
            bonusShapeFar, state.enchantView().bonusPile());
    }

    @Test
    public void despawningTheMarkedPileFallsBackToAnotherPileOfTheSameShape() {
        GameObject near = pileAt(Shape.CUBE, NEAR_PILE_AT);
        GameObject far = pileAt(Shape.CUBE, FAR_PILE_AT);
        room.onGameObjectSpawned(far);
        room.onGameObjectSpawned(near);
        room.onTick();
        assertEquals(near, state.enchantView().bonusPile());

        room.onGameObjectDespawned(near);
        room.onTick();
        assertEquals("the far pile of the same shape is still there to fall back to",
            far, state.enchantView().bonusPile());
    }

    @Test
    public void countsWhatIsLeftOfTheWindow() {
        room.onTick();
        showShape(Shape.CYLINDER);
        tickTo(130);
        assertEquals(40, state.enchantView().ticksLeft());
        tickTo(140);
        assertEquals(30, state.enchantView().ticksLeft());
    }

    @Test
    public void theCountFallsAsTheHandFills() {
        room.onTick();
        showShape(Shape.CYLINDER);
        tickTo(130);
        int empty = state.enchantView().pickups();

        Item shape = org.mockito.Mockito.mock(Item.class);
        when(shape.getId()).thenReturn(ItemID.MAGICTRAINING_ENCHAN_CYLINDER);
        when(inventory.getItems()).thenReturn(new Item[]{shape, shape});
        tickTo(130);
        assertTrue("holding shapes must lower the count", state.enchantView().pickups() < empty);
    }

    @Test
    public void finishedOrbsDoNotCountAgainstYou() {
        room.onTick();
        showShape(Shape.CYLINDER);
        tickTo(130);
        int empty = state.enchantView().pickups();

        Item orb = org.mockito.Mockito.mock(Item.class);
        when(orb.getId()).thenReturn(ItemID.MAGICTRAINING_ENCHAN_SHAPEORB);
        when(inventory.getItems()).thenReturn(new Item[]{orb, orb, orb});
        tickTo(130);
        assertEquals("orbs are done, they cost no more time", empty, state.enchantView().pickups());
    }

    @Test
    public void theSettingSilencesTheCount() {
        when(config.showPickupCount()).thenReturn(false);
        room.onTick();
        showShape(Shape.CYLINDER);
        tickTo(130);
        assertEquals(-1, state.enchantView().pickups());
    }

    @Test
    public void standDownStopsEverything() {
        room.onGameObjectSpawned(cubePile);
        room.onTick();
        assertNotNull(state.enchantView());
        room.standDown();
        assertNull(state.enchantView());
    }

    @Test
    public void aSceneReloadForgetsThePiles() {
        room.onGameObjectSpawned(cubePile);
        room.onTick();
        assertEquals(cubePile, state.enchantView().bonusPile());
        room.onSceneLoading();
        room.onTick();
        assertNull("the pile reference is stale after a reload", state.enchantView().bonusPile());
    }

    @Test
    public void leavingTheRoomForgetsTheWindow() {
        // Five minutes in another room and the anchor is a guess dressed up as a fact.
        room.onTick();
        showShape(Shape.CYLINDER);
        tickTo(130);
        assertTrue(state.enchantView().timingKnown());

        room.standDown();
        tickTo(1500);
        assertNotNull("the shape is readable the moment we are back", state.enchantView().shape());
        assertEquals(false, state.enchantView().timingKnown());
    }

    @Test
    public void aSceneReloadForgetsTheWindow() {
        // A hop or a relog in the room never reaches standDown, and the tick count starts over.
        room.onTick();
        showShape(Shape.CYLINDER);
        tickTo(130);
        assertTrue(state.enchantView().timingKnown());

        room.onSceneLoading();
        tickTo(20);
        assertNotNull("the shape is readable the moment we are back", state.enchantView().shape());
        assertEquals(false, state.enchantView().timingKnown());
    }

    @Test
    public void neverTouchesTheHintArrow() {
        // Core points the client's single hint arrow at the nearest dragonstone in this room.
        room.onGameObjectSpawned(cubePile);
        room.onTick();
        showShape(Shape.CYLINDER);
        tickTo(130);
        room.standDown();
        room.reset();
        verify(client, never()).setHintArrow(any(net.runelite.api.coords.WorldPoint.class));
        verify(client, never()).clearHintArrow();
    }

    private static final WorldPoint STONE_AT = new WorldPoint(3360, 9630, 0);

    private Tile tileAt(WorldPoint point) {
        Tile tile = org.mockito.Mockito.mock(Tile.class);
        when(tile.getWorldLocation()).thenReturn(point);
        return tile;
    }

    private TileItem itemWithId(int id) {
        TileItem item = org.mockito.Mockito.mock(TileItem.class);
        when(item.getId()).thenReturn(id);
        return item;
    }

    @Test
    public void tracksDragonstonesOnTheFloor() {
        when(config.highlightDragonstones()).thenReturn(true);
        TileItem stone = itemWithId(ItemID.MAGICTRAINING_DRAGONSTONE);

        room.onItemSpawned(stone, tileAt(STONE_AT));
        room.onTick();
        assertEquals(Collections.singletonList(STONE_AT), state.dragonstones());

        room.onItemDespawned(stone, tileAt(STONE_AT));
        room.onTick();
        assertTrue(state.dragonstones().isEmpty());
    }

    @Test
    public void despawningOneStoneLeavesTheOthersWhereTheyAre() {
        // With a single stone on the floor, clearing the list looks the same as removing the right
        // entry. Two stones tell them apart.
        WorldPoint otherAt = new WorldPoint(3364, 9634, 0);
        when(config.highlightDragonstones()).thenReturn(true);
        TileItem stone = itemWithId(ItemID.MAGICTRAINING_DRAGONSTONE);

        room.onItemSpawned(stone, tileAt(STONE_AT));
        room.onItemSpawned(stone, tileAt(otherAt));
        room.onTick();
        assertEquals(2, state.dragonstones().size());

        room.onItemDespawned(stone, tileAt(STONE_AT));
        room.onTick();
        assertEquals(Collections.singletonList(otherAt), state.dragonstones());
    }

    @Test
    public void twoStonesOnOneTileAreBothTracked() {
        // Stones stack, so the list must count them rather than deduplicate by location.
        when(config.highlightDragonstones()).thenReturn(true);
        TileItem stone = itemWithId(ItemID.MAGICTRAINING_DRAGONSTONE);

        room.onItemSpawned(stone, tileAt(STONE_AT));
        room.onItemSpawned(stone, tileAt(STONE_AT));
        room.onTick();
        assertEquals(2, state.dragonstones().size());

        room.onItemDespawned(stone, tileAt(STONE_AT));
        room.onTick();
        assertEquals(Collections.singletonList(STONE_AT), state.dragonstones());
    }

    @Test
    public void ignoresGroundItemsThatAreNotDragonstones() {
        when(config.highlightDragonstones()).thenReturn(true);
        room.onItemSpawned(itemWithId(ItemID.MAGICTRAINING_ENCHAN_CUBE), tileAt(STONE_AT));
        room.onTick();
        assertTrue(state.dragonstones().isEmpty());
    }

    @Test
    public void theSettingSilencesTheDragonstones() {
        when(config.highlightDragonstones()).thenReturn(false);
        room.onItemSpawned(itemWithId(ItemID.MAGICTRAINING_DRAGONSTONE), tileAt(STONE_AT));
        room.onTick();
        assertTrue(state.dragonstones().isEmpty());
    }

    @Test
    public void dragonstonesStillShowWhenTheBonusShapeCannotBeRead() {
        // No model widget is unhidden for a moment on the way in. Neither may take the stone
        // outlines down with it.
        when(config.highlightDragonstones()).thenReturn(true);
        showShape(null);

        room.onItemSpawned(itemWithId(ItemID.MAGICTRAINING_DRAGONSTONE), tileAt(STONE_AT));
        room.onTick();

        assertEquals(Collections.singletonList(STONE_AT), state.dragonstones());
        assertNull("no shape to draw, but the stones stay", state.enchantView());
    }

    @Test
    public void standDownDropsTheDragonstones() {
        when(config.highlightDragonstones()).thenReturn(true);
        room.onItemSpawned(itemWithId(ItemID.MAGICTRAINING_DRAGONSTONE), tileAt(STONE_AT));
        room.onTick();
        assertTrue(!state.dragonstones().isEmpty());
        room.standDown();
        assertTrue(state.dragonstones().isEmpty());
    }
}

package com.lazybones;

