    public void boneValuesMapOneToFour() {
        assertEquals(1, GraveyardIds.boneValue(6904));
        assertEquals(2, GraveyardIds.boneValue(6905));
        assertEquals(3, GraveyardIds.boneValue(6906));
        assertEquals(4, GraveyardIds.boneValue(6907));
