    }

    @Test
    public void pileValuesMapOneToFour() {
        assertEquals(1, GraveyardIds.pileValue(10725));
        assertEquals(4, GraveyardIds.pileValue(10728));
        assertEquals(0, GraveyardIds.pileValue(10735)); // chute is not a pile
    }

    @Test
    public void predicates() {
        assertTrue(GraveyardIds.isPile(10726));
        assertFalse(GraveyardIds.isPile(9999));
