import net.runelite.api.gameval.InventoryID;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class GraveyardRoomTest {

    // Region 13462 runs from (3328, 9600); the graveyard sits on plane 2 of it.
    private static final WorldPoint PLAYER = new WorldPoint(3360, 9640, 2);
    private static final WorldPoint PILE = new WorldPoint(3361, 9640, 2);
    private static final WorldPoint CHUTE = new WorldPoint(3363, 9640, 2);
    // Somewhere the arena plugin might point instead - a dragonstone one floor down.
    private static final WorldPoint ELSEWHERE = new WorldPoint(3363, 9645, 0);

    private Client client;
    private LazyBonesConfig config;
    private GraveyardScene scene;
    private LazyBonesState state;
    private GraveyardRoom room;

    @Before
    public void setUp() {
        client = mock(Client.class);
        config = mock(LazyBonesConfig.class);
        scene = new GraveyardScene();
        state = new LazyBonesState();
        room = new GraveyardRoom(client, config, scene, state);

        when(config.spell()).thenReturn(Spell.BONES_TO_PEACHES);
        when(config.showDepositArrow()).thenReturn(true);

        Player player = mock(Player.class);
        when(player.getWorldLocation()).thenReturn(PLAYER);
        when(client.getLocalPlayer()).thenReturn(player);
    }

    private static GameObject object(int id, WorldPoint at) {
        GameObject o = mock(GameObject.class);
        when(o.getId()).thenReturn(id);
        when(o.getWorldLocation()).thenReturn(at);
        return o;
    }

    /** Spawn a chute, hold a peach, tick: that is the deposit phase, which sets the arrow. */
    private void tickIntoDeposit() {
        room.onGameObjectSpawned(object(GraveyardIds.FOOD_CHUTE, CHUTE));
        Item peach = mock(Item.class);
        when(peach.getId()).thenReturn(GraveyardIds.PEACH);
        ItemContainer inv = mock(ItemContainer.class);
        when(inv.getItems()).thenReturn(new Item[]{peach});
        when(client.getItemContainer(InventoryID.INV)).thenReturn(inv);
        room.onTick();
    }

    /** Pretend the arrow is exactly where we left it. */
    private void arrowStillOurs() {
        when(client.getHintArrowType()).thenReturn(HintArrowType.COORDINATE);
        when(client.getHintArrowPoint()).thenReturn(CHUTE);
    }

    @Test
    public void depositPhasePointsTheArrowAtTheChute() {
        tickIntoDeposit();
        assertEquals(Phase.DEPOSIT, state.phase());
        verify(client).setHintArrow(CHUTE);
    }

    @Test
    public void standDownClearsOurOwnArrow() {
        tickIntoDeposit();
        arrowStillOurs();

        room.standDown();

        verify(client).clearHintArrow();
    }

    @Test
    public void standDownLeavesAnArrowAnotherPluginMovedAlone() {
        tickIntoDeposit();
        // The arena plugin pointed the client's one arrow somewhere else after we set ours.
        when(client.getHintArrowType()).thenReturn(HintArrowType.COORDINATE);
        when(client.getHintArrowPoint()).thenReturn(ELSEWHERE);

        room.standDown();

        verify(client, never()).clearHintArrow();
    }

    @Test
    public void standDownLeavesAnArrowOfAnotherTypeAlone() {
        tickIntoDeposit();
        // An NPC arrow is not ours whatever the coordinate reads back as.
        when(client.getHintArrowType()).thenReturn(HintArrowType.NPC);
        when(client.getHintArrowPoint()).thenReturn(CHUTE);

        room.standDown();

        verify(client, never()).clearHintArrow();
    }

    @Test
    public void standDownWithoutAnArrowNeverTouchesTheClientsOne() {
        room.standDown();

        verify(client, never()).getHintArrowType();
        verify(client, never()).clearHintArrow();
    }

    @Test
    public void standDownStopsTheOverlaysDrawing() {
        tickIntoDeposit();
        arrowStillOurs();

        room.standDown();

        assertNull(state.phase());
        assertNull(state.chute());
        assertTrue(state.pileMarks().isEmpty());
    }

    @Test
    public void standDownKeepsTheScene() {
        room.onGameObjectSpawned(object(GraveyardIds.PILE_VALUE_2, PILE));

        room.standDown();

        assertTrue(scene.active());
        assertEquals(1, scene.nearestPiles(PLAYER, 4).size());
        assertEquals(2, scene.nearestPiles(PLAYER, 1).get(0).state().currentValue());
    }

    @Test
    public void guidesAgainAfterStandingDownWithoutASceneReload() {
        tickIntoDeposit();
        arrowStillOurs();
        room.standDown();

        room.onTick();

        assertEquals(Phase.DEPOSIT, state.phase());
        verify(client, times(2)).setHintArrow(CHUTE);
    }

    @Test
    public void resetEmptiesTheScene() {
        room.onGameObjectSpawned(object(GraveyardIds.PILE_VALUE_2, PILE));
        assertTrue(scene.active());

        room.reset();

        assertFalse(scene.active());
        assertTrue(scene.nearestPiles(PLAYER, 4).isEmpty());
    }
}

