import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class InventoryReaderTest {
    private static Item item(int id, int qty) {
        Item it = mock(Item.class);
        when(it.getId()).thenReturn(id);
        when(it.getQuantity()).thenReturn(qty);
        return it;
    }

    @Test
    public void sumsBoneValuesAndCountsCapacity() {
        // 3 bones (values 1,2,3) + 2 non-bone items (staff, runes), rest empty.
        Item[] items = {
            item(6904, 1), item(6905, 1), item(6906, 1),
            item(1381, 1), item(555, 5000), item(-1, 0)
        };
        InventorySnapshot s = InventoryReader.read(items, Spell.BONES_TO_PEACHES);
        assertEquals(1 + 2 + 3, s.heldValue());
        assertEquals(28 - 2, s.capacity()); // 2 non-bone/non-fruit items
        assertEquals(0, s.fruitCount());
        assertFalse(s.holdingFruit());
    }

    @Test
    public void countsFruitForConfiguredSpell() {
        Item[] items = { item(6883, 1), item(6883, 1) }; // two peaches
        InventorySnapshot s = InventoryReader.read(items, Spell.BONES_TO_PEACHES);
        assertEquals(2, s.fruitCount());
        assertTrue(s.holdingFruit());
        assertEquals(0, s.heldValue());
    }

    @Test
    public void nullInventoryIsEmptyFullCapacity() {
        InventorySnapshot s = InventoryReader.read(null, Spell.BONES_TO_BANANAS);
        assertEquals(0, s.heldValue());
        assertEquals(28, s.capacity());
        assertFalse(s.holdingFruit());
    }
}

