package com.lazybones;

import com.lazybones.enchant.Shape;
import java.util.Arrays;
import java.util.Collections;
import net.runelite.api.GameObject;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class LazyBonesStateTest {
    @Test
    public void holdsAndClears() {
        LazyBonesState s = new LazyBonesState();
        s.setPhase(Phase.COLLECT);
        s.setSpell(Spell.BONES_TO_PEACHES);
        s.setPileMarks(Arrays.asList(new PileMark(null, 3)));
        assertEquals(Phase.COLLECT, s.phase());
        assertEquals(1, s.pileMarks().size());

        s.clear();
        assertNull(s.phase());
        assertTrue(s.pileMarks().isEmpty());
        assertNull(s.chute());
        assertEquals(Spell.BONES_TO_PEACHES, s.spell());
    }

    // The four clear methods own disjoint sets of fields, and that is the whole point of there being
    // four of them: the plugin stands every room the player is not in down on the same tick it writes
    // the room they are in, so a clear that reaches past its own fields blanks a display the moment it
    // was filled. Each of the four tests below fills all four groups, clears one, and checks the other
    // three came through it whole.

    private LazyBonesState populated() {
        LazyBonesState s = new LazyBonesState();
        s.setPhase(Phase.COLLECT);
        s.setPileMarks(Arrays.asList(new PileMark(null, 3)));
        s.setChute(Mockito.mock(GameObject.class));

        s.setRoom(Room.ENCHANTMENT);
        s.setSpellStatus(new SpellStatus(RoomSpell.TELEKINETIC_GRAB, Availability.AVAILABLE, 33, 70));
        s.setMtaWarning(MtaWarning.PLUGIN_OFF);

        s.setFreeCupboards(Collections.singletonList(Mockito.mock(GameObject.class)));
        s.setFreeItemIds(Collections.singleton(7));

        s.setEnchantView(new EnchantView(Shape.CUBE, null, true, 20, 40, 2));
        s.setDragonstones(Collections.singletonList(new WorldPoint(3360, 9630, 0)));
        return s;
    }

    private void assertGraveyardHeld(LazyBonesState s) {
        assertEquals(Phase.COLLECT, s.phase());
        assertEquals(1, s.pileMarks().size());
        assertNotNull(s.chute());
    }

    private void assertRoomStatusHeld(LazyBonesState s) {
        assertEquals(Room.ENCHANTMENT, s.room());
        assertNotNull(s.spellStatus());
        assertEquals(MtaWarning.PLUGIN_OFF, s.mtaWarning());
    }

    private void assertAlchemyHeld(LazyBonesState s) {
        assertEquals(1, s.freeCupboards().size());
        assertEquals(1, s.freeItemIds().size());
    }

    private void assertEnchantingHeld(LazyBonesState s) {
        assertNotNull(s.enchantView());
        assertEquals(1, s.dragonstones().size());
    }

    @Test
    public void clearLeavesTheOtherThreeGroupsAlone() {
        LazyBonesState s = populated();
        s.clear();

        assertNull(s.phase());
        assertTrue(s.pileMarks().isEmpty());
        assertNull(s.chute());

        assertRoomStatusHeld(s);
        assertAlchemyHeld(s);
        assertEnchantingHeld(s);
    }

    @Test
    public void clearRoomStatusLeavesTheOtherThreeGroupsAlone() {
        LazyBonesState s = populated();
        s.clearRoomStatus();

        assertEquals(Room.NONE, s.room());
        assertNull(s.spellStatus());
        assertEquals(MtaWarning.NONE, s.mtaWarning());

        assertGraveyardHeld(s);
        assertAlchemyHeld(s);
        assertEnchantingHeld(s);
    }

    @Test
    public void clearAlchemyLeavesTheOtherThreeGroupsAlone() {
        LazyBonesState s = populated();
        s.clearAlchemy();

        assertTrue(s.freeCupboards().isEmpty());
        assertTrue(s.freeItemIds().isEmpty());

        assertGraveyardHeld(s);
        assertRoomStatusHeld(s);
        assertEnchantingHeld(s);
    }

    @Test
    public void clearEnchantingLeavesTheOtherThreeGroupsAlone() {
        LazyBonesState s = populated();
        s.clearEnchanting();

        assertNull(s.enchantView());
        assertTrue(s.dragonstones().isEmpty());

        assertGraveyardHeld(s);
        assertRoomStatusHeld(s);
        assertAlchemyHeld(s);
    }

    @Test
    public void noClearMethodIsAWholeReset() {
        // A guard on the guards: if populated() ever stopped filling something, the four tests above
        // would pass over an empty field and prove nothing.
        LazyBonesState s = populated();
        assertGraveyardHeld(s);
        assertRoomStatusHeld(s);
        assertAlchemyHeld(s);
        assertEnchantingHeld(s);
        assertFalse(s.dragonstones().isEmpty());
    }
}

package com.lazybones;

import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.widgets.Widget;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.when;

public class MtaLocationTest {

    // Region 13462 is ((3360 >> 6) << 8) | (9630 >> 6) = (52 << 8) | 150. The formula does not use
    // the plane, so all three shared-region rooms sit at this x/y and differ only by plane.
    private static final int ARENA_X = 3360;
    private static final int ARENA_Y = 9630;
    private static final int PLANE_ENCHANTMENT = 0;
    private static final int PLANE_GRAVEYARD = 1;
    private static final int PLANE_ALCHEMY = 2;
    private static final int PLANE_UNEXPECTED = 3;

    private static final WorldPoint LUMBRIDGE = new WorldPoint(3200, 3200, 0);

    @Mock private Client client;
    @Mock private Player player;
    @Mock private Widget widget;

    private MtaLocation location;

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
        location = new MtaLocation(client);
        when(client.getLocalPlayer()).thenReturn(player);
        when(client.getWidget(anyInt())).thenReturn(null);
    }

    private static WorldPoint arena(int plane) {
        return new WorldPoint(ARENA_X, ARENA_Y, plane);
    }

    @Test
    public void noPlayerIsNone() {
        when(client.getLocalPlayer()).thenReturn(null);
        assertEquals(Room.NONE, location.current());
    }

    @Test
    public void outsideTheArenaIsNone() {
        when(player.getWorldLocation()).thenReturn(LUMBRIDGE);
        when(client.getWidget(Room.GRAVEYARD.rootComponent())).thenReturn(widget);
        assertEquals(Room.NONE, location.current());
    }

    @Test
    public void insideTheArenaWithNoRoomWidgetIsNone() {
        when(player.getWorldLocation()).thenReturn(arena(PLANE_ENCHANTMENT));
        assertEquals(Room.NONE, location.current());
    }

    @Test
    public void graveyardWidgetInsideTheArenaIsGraveyard() {
        when(player.getWorldLocation()).thenReturn(arena(PLANE_GRAVEYARD));
        when(client.getWidget(Room.GRAVEYARD.rootComponent())).thenReturn(widget);
        assertEquals(Room.GRAVEYARD, location.current());
    }

    @Test
    public void eachSharedRegionRoomIsIdentifiedByItsOwnPlane() {
        assertRoomAtPlane(Room.ENCHANTMENT, PLANE_ENCHANTMENT);
        assertRoomAtPlane(Room.GRAVEYARD, PLANE_GRAVEYARD);
        assertRoomAtPlane(Room.ALCHEMY, PLANE_ALCHEMY);
    }

    private void assertRoomAtPlane(Room room, int plane) {
        when(client.getWidget(anyInt())).thenReturn(null);
        when(player.getWorldLocation()).thenReturn(arena(plane));
        when(client.getWidget(room.rootComponent())).thenReturn(widget);
        assertEquals(room, location.current());
    }

    @Test
    public void alchemyWidgetLeftOverOnTheGraveyardPlaneStillReadsGraveyard() {
        // The exact regression from the smoke run: the Alchemist's Playground widget stays loaded
        // after the player leaves it, so a leftover ALCHEMY widget must not outrank the plane the
        // player is actually standing on. Before this fix, enum order made ALCHEMY win here.
        when(player.getWorldLocation()).thenReturn(arena(PLANE_GRAVEYARD));
        when(client.getWidget(Room.GRAVEYARD.rootComponent())).thenReturn(widget);
        when(client.getWidget(Room.ALCHEMY.rootComponent())).thenReturn(widget);
        assertEquals(Room.GRAVEYARD, location.current());
    }

    @Test
    public void unexpectedPlaneInsideTheArenaIsNone() {
        // Even with a room widget present, a plane outside 0/1/2 is not one the arena assigns.
        when(player.getWorldLocation()).thenReturn(arena(PLANE_UNEXPECTED));
        when(client.getWidget(Room.ENCHANTMENT.rootComponent())).thenReturn(widget);
        assertEquals(Room.NONE, location.current());
    }

    @Test
    public void telekineticWidgetOutsideTheArenaRegionIsTelekinetic() {
        when(player.getWorldLocation()).thenReturn(LUMBRIDGE);
        when(client.getWidget(Room.TELEKINETIC.rootComponent())).thenReturn(widget);
        assertEquals(Room.TELEKINETIC, location.current());
    }

    @Test
    public void everyRoomHasADistinctRootComponent() {
        for (Room a : Room.values()) {
            for (Room b : Room.values()) {
                if (a != b && a != Room.NONE && b != Room.NONE) {
                    assertNotEquals(a + " and " + b + " share a root component",
                        a.rootComponent(), b.rootComponent());
                }
            }
        }
    }
}

package com.lazybones;

import net.runelite.client.config.ConfigManager;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.when;

public class MtaPluginStatusTest {

    @Mock private ConfigManager configManager;
    private MtaPluginStatus status;

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
        status = new MtaPluginStatus(configManager);
    }

    private void pluginEnabled(String value) {
        when(configManager.getConfiguration("runelite", "mtaplugin")).thenReturn(value);
    }

    private void roomOverlay(String key, String value) {
        when(configManager.getConfiguration("mta", key)).thenReturn(value);
    }

    @Test
    public void neverSetMeansOffBecauseMtaIsNotEnabledByDefault() {
        pluginEnabled(null);
        assertEquals(MtaWarning.PLUGIN_OFF, status.warningFor(Room.GRAVEYARD));
    }

    @Test
    public void explicitlyDisabledIsPluginOff() {
        pluginEnabled("false");
        assertEquals(MtaWarning.PLUGIN_OFF, status.warningFor(Room.GRAVEYARD));
    }

    @Test
    public void enabledWithTheRoomOnIsNoWarning() {
        pluginEnabled("true");
        roomOverlay("graveyard", "true");
        assertEquals(MtaWarning.NONE, status.warningFor(Room.GRAVEYARD));
    }

    @Test
    public void roomKeyNeverSetMeansOnBecauseMtaDefaultsItTrue() {
        pluginEnabled("true");
        roomOverlay("graveyard", null);
        assertEquals(MtaWarning.NONE, status.warningFor(Room.GRAVEYARD));
    }

    @Test
    public void enabledWithTheRoomOffIsRoomOff() {
        pluginEnabled("true");
        roomOverlay("graveyard", "false");
        assertEquals(MtaWarning.ROOM_OFF, status.warningFor(Room.GRAVEYARD));
    }

    @Test
    public void pluginOffOutranksRoomOff() {
        pluginEnabled("false");
        roomOverlay("graveyard", "false");
        assertEquals(MtaWarning.PLUGIN_OFF, status.warningFor(Room.GRAVEYARD));
    }

    @Test
    public void outsideAnyRoomThereIsNothingToWarnAbout() {
        pluginEnabled("false");
        assertEquals(MtaWarning.NONE, status.warningFor(Room.NONE));
    }

    @Test
    public void eachRoomReadsItsOwnKey() {
        pluginEnabled("true");
        roomOverlay("alchemy", "false");
        roomOverlay("enchantment", "true");
        assertEquals(MtaWarning.ROOM_OFF, status.warningFor(Room.ALCHEMY));
        assertEquals(MtaWarning.NONE, status.warningFor(Room.ENCHANTMENT));
    }
}

