package com.lazybones;

import org.junit.Test;
import static org.junit.Assert.assertEquals;

public class PhaseModelTest {
    @Test
    public void holdingFruitIsDeposit() {
        InventorySnapshot inv = new InventorySnapshot(0, 28, 24);
        assertEquals(Phase.DEPOSIT, PhaseModel.phaseFor(inv, Spell.BONES_TO_PEACHES));
    }

    @Test
    public void atTargetIsCast() {
        InventorySnapshot inv = new InventorySnapshot(24, 28, 0); // peaches target = 24
        assertEquals(Phase.CAST, PhaseModel.phaseFor(inv, Spell.BONES_TO_PEACHES));
    }

    @Test
    public void belowTargetIsCollect() {
        InventorySnapshot inv = new InventorySnapshot(10, 28, 0);
        assertEquals(Phase.COLLECT, PhaseModel.phaseFor(inv, Spell.BONES_TO_PEACHES));
    }

    @Test
    public void depositWinsEvenIfBonesPresent() {
        // A stray bone plus fruit still means "go deposit".
        InventorySnapshot inv = new InventorySnapshot(2, 28, 20);
        assertEquals(Phase.DEPOSIT, PhaseModel.phaseFor(inv, Spell.BONES_TO_BANANAS));
    }

    @Test
    public void depositBeatsCastWhenHoldingFruitAtTarget() {
        // heldValue >= target AND holding fruit: DEPOSIT must win over CAST (order matters).
        InventorySnapshot inv = new InventorySnapshot(28, 28, 5);
        assertEquals(Phase.DEPOSIT, PhaseModel.phaseFor(inv, Spell.BONES_TO_BANANAS));
    }

    @Test
    public void emptyHandedFullInventoryIsCollectNotCast() {
        // No bones, capacity 0 (a full pack of non-bone items) -> target 0, but 0 >= 0 must NOT read as
        // CAST, or a full inventory in another MTA room would falsely prompt a cast.
        InventorySnapshot inv = new InventorySnapshot(0, 0, 0);
        assertEquals(Phase.COLLECT, PhaseModel.phaseFor(inv, Spell.BONES_TO_BANANAS));
        assertEquals(Phase.COLLECT, PhaseModel.phaseFor(inv, Spell.BONES_TO_PEACHES));
    }
}

package com.lazybones;

import org.junit.Test;
import static org.junit.Assert.assertEquals;

public class PileCycleStateTest {
    @Test
    public void countsUpThenAutoAdvancesAfterFour() {
        PileCycleState s = new PileCycleState(1);
        for (int i = 0; i < 4; i++) s.recordBoneReceived(1);
        assertEquals(2, s.currentValue());     // auto-advanced 1 -> 2
        assertEquals(0, s.takenOfThisType());
    }

    @Test
    public void objectSwapReanchorsAndResetsCount() {
        PileCycleState s = new PileCycleState(1);
        s.recordBoneReceived(1);
        s.recordBoneReceived(1);               // taken = 2 of value 1
        s.syncToObjectValue(2);                // pile flipped early (visible model changed)
        assertEquals(2, s.currentValue());
        assertEquals(0, s.takenOfThisType());
    }

    @Test
    public void unexpectedBoneReanchorsFromOne() {
        PileCycleState s = new PileCycleState(1);
        s.recordBoneReceived(1);
        s.recordBoneReceived(1);               // taken = 2 of value 1
        s.recordBoneReceived(2);               // flipped after only 2 - got a value-2 bone
        assertEquals(2, s.currentValue());
        assertEquals(1, s.takenOfThisType());  // counting the new type from 1
    }

    @Test
    public void syncToSameValueIsNoOp() {
        PileCycleState s = new PileCycleState(3);
        s.recordBoneReceived(3);               // taken = 1
        s.syncToObjectValue(3);
        assertEquals(3, s.currentValue());
        assertEquals(1, s.takenOfThisType());
    }

    @Test
    public void wrapsFromFourToOneAfterFour() {
        PileCycleState s = new PileCycleState(4);
        for (int i = 0; i < 4; i++) s.recordBoneReceived(4);
        assertEquals(1, s.currentValue());     // 4 -> 1 wrap after the fourth value-4 bone
        assertEquals(0, s.takenOfThisType());
    }

    @Test
    public void zeroValueIsIgnored() {
        PileCycleState s = new PileCycleState(2);
        s.recordBoneReceived(2);               // taken = 1
        s.recordBoneReceived(0);               // ignored - no such bone
        s.syncToObjectValue(0);                // ignored - unknown object value
        assertEquals(2, s.currentValue());
        assertEquals(1, s.takenOfThisType());
    }
}

