package com.lazybones;

import java.util.Arrays;
import java.util.List;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.assertEquals;

public class SceneMathTest {
    @Test
    public void picksNearestTwoInDistanceOrder() {
        WorldPoint from = new WorldPoint(3000, 3000, 0);
        List<WorldPoint> pts = Arrays.asList(
            new WorldPoint(3010, 3000, 0), // dist 10
            new WorldPoint(3002, 3000, 0), // dist 2
            new WorldPoint(3005, 3000, 0)  // dist 5
        );
        assertEquals(Arrays.asList(1, 2), SceneMath.nearestIndices(from, pts, 2));
    }

    @Test
    public void clampsToAvailableCount() {
        WorldPoint from = new WorldPoint(3000, 3000, 0);
        List<WorldPoint> pts = Arrays.asList(new WorldPoint(3001, 3000, 0));
        assertEquals(Arrays.asList(0), SceneMath.nearestIndices(from, pts, 4));
    }
}

package com.lazybones;

import java.util.HashSet;
import java.util.Set;
import net.runelite.api.gameval.SpriteID;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.lenient;
import static org.mockito.Mockito.when;

public class SpellAvailabilityTest {

    private static final int STANDARD_BOOK = 0;
    private static final int ANCIENT_BOOK = 1;
    private static final int NO_WIDGET = -1;

    private static final RoomSpell GRAB = RoomSpell.TELEKINETIC_GRAB;
    private static final int GRAB_ON_SPRITE = SpriteID.Magicon.TELEKINETIC_GRAB;
    private static final int GRAB_OFF_SPRITE = SpriteID.Magicoff.TELEKINETIC_GRAB;
    private static final int PEACHES_OFF_SPRITE = SpriteID.Magicoff2.BONES_TO_PEACHES;

    @Mock private LazyBonesConfig config;

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
        // lenient: each test exercises one room, so the other rooms' settings go unread.
        lenient().when(config.spell()).thenReturn(Spell.BONES_TO_PEACHES);
        lenient().when(config.alchemySpell()).thenReturn(AlchemySpell.HIGH_LEVEL);
    }

    @Test
    public void onSpriteIsAvailable() {
        assertEquals(Availability.AVAILABLE, SpellAvailability.evaluate(
            GRAB, STANDARD_BOOK, true, 99, 33, GRAB_ON_SPRITE));
    }

    @Test
    public void offSpriteWithEverythingElseFineIsMissingRunes() {
        assertEquals(Availability.MISSING_RUNES, SpellAvailability.evaluate(
            GRAB, STANDARD_BOOK, true, 99, 33, GRAB_OFF_SPRITE));
    }

    @Test
    public void lowLevelIsLevel() {
        assertEquals(Availability.LEVEL, SpellAvailability.evaluate(
            GRAB, STANDARD_BOOK, true, 32, 33, GRAB_OFF_SPRITE));
    }

    @Test
    public void boostToRequirementIsNotLevel() {
        // A boost genuinely lets you cast, so the boosted level is what counts.
        assertEquals(Availability.AVAILABLE, SpellAvailability.evaluate(
            GRAB, STANDARD_BOOK, true, 33, 33, GRAB_ON_SPRITE));
    }

    @Test
    public void wrongSpellbookBeatsEverything() {
        // Ancient book, low level, locked, off sprite: the book is still the thing to say.
        assertEquals(Availability.WRONG_SPELLBOOK, SpellAvailability.evaluate(
            RoomSpell.BONES_TO_PEACHES, ANCIENT_BOOK, false, 1, 60, PEACHES_OFF_SPRITE));
    }

    @Test
    public void lockedBeatsLevel() {
        assertEquals(Availability.NOT_UNLOCKED, SpellAvailability.evaluate(
            RoomSpell.BONES_TO_PEACHES, STANDARD_BOOK, false, 1, 60, PEACHES_OFF_SPRITE));
    }

    @Test
    public void levelBeatsMissingRunes() {
        assertEquals(Availability.LEVEL, SpellAvailability.evaluate(
            RoomSpell.BONES_TO_PEACHES, STANDARD_BOOK, true, 59, 60, PEACHES_OFF_SPRITE));
    }

    @Test
    public void missingWidgetIsUnknown() {
        assertEquals(Availability.UNKNOWN, SpellAvailability.evaluate(
            GRAB, STANDARD_BOOK, true, 99, 33, NO_WIDGET));
    }

    @Test
    public void unrecognisedSpriteIsUnknown() {
        assertEquals(Availability.UNKNOWN, SpellAvailability.evaluate(
            GRAB, STANDARD_BOOK, true, 99, 33, 999999));
    }

    @Test
    public void unknownLevelRequirementSkipsTheLevelCheck() {
        // A cache lookup that came back empty must not be read as "requires level 0".
        assertEquals(Availability.MISSING_RUNES, SpellAvailability.evaluate(
            GRAB, STANDARD_BOOK, true, 1, 0, GRAB_OFF_SPRITE));
    }

    @Test
    public void graveyardSpellFollowsTheConfiguredSpell() {
        when(config.spell()).thenReturn(Spell.BONES_TO_PEACHES);
        assertEquals(RoomSpell.BONES_TO_PEACHES, RoomSpell.forRoom(Room.GRAVEYARD, config, 99));
        when(config.spell()).thenReturn(Spell.BONES_TO_BANANAS);
        assertEquals(RoomSpell.BONES_TO_BANANAS, RoomSpell.forRoom(Room.GRAVEYARD, config, 99));
    }

    @Test
    public void telekineticAlwaysNeedsGrab() {
        assertEquals(RoomSpell.TELEKINETIC_GRAB, RoomSpell.forRoom(Room.TELEKINETIC, config, 99));
    }

    @Test
    public void roomsWithoutASpellYetReturnNull() {
        assertNull(RoomSpell.forRoom(Room.NONE, config, 99));
    }

    @Test
    public void alchemyRoomFollowsTheConfiguredAlchemySpell() {
        when(config.alchemySpell()).thenReturn(AlchemySpell.HIGH_LEVEL);
        assertEquals(RoomSpell.HIGH_ALCHEMY, RoomSpell.forRoom(Room.ALCHEMY, config, 99));
        when(config.alchemySpell()).thenReturn(AlchemySpell.LOW_LEVEL);
        assertEquals(RoomSpell.LOW_ALCHEMY, RoomSpell.forRoom(Room.ALCHEMY, config, 99));
    }

    @Test
    public void everyAlchemySpellMapsToADistinctRoomSpell() {
        Set<RoomSpell> mapped = new HashSet<>();
        for (AlchemySpell alchemy : AlchemySpell.values()) {
            assertNotNull(alchemy + " maps to nothing", alchemy.roomSpell());
            assertTrue(alchemy + " repeats another spell", mapped.add(alchemy.roomSpell()));
        }
    }

    @Test
    public void theEnchantingRoomFollowsTheConfiguredChoice() {
        when(config.enchantChoice()).thenReturn(EnchantChoice.LVL_4);
        assertEquals(RoomSpell.ENCHANT_4, RoomSpell.forRoom(Room.ENCHANTMENT, config, 99));
        when(config.enchantChoice()).thenReturn(EnchantChoice.AUTO);
        assertEquals(RoomSpell.ENCHANT_3, RoomSpell.forRoom(Room.ENCHANTMENT, config, 50));
    }
}

