package com.lazybones;

import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.ItemComposition;
import net.runelite.api.ParamID;
import net.runelite.api.Skill;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class SpellbookReaderTest {

    private static final int BOOK_ENUM = 2000;
    private static final int SPELL_LIST_ENUM = 3000;
    private static final int GRAB_OBJ = 4000;
    private static final int GRAB_ON_SPRITE = SpriteID.Magicon.TELEKINETIC_GRAB;
    private static final int GRAB_OFF_SPRITE = SpriteID.Magicoff.TELEKINETIC_GRAB;

    @Mock private Client client;
    @Mock private EnumComposition spellbooksSub;
    @Mock private EnumComposition bookEnum;
    @Mock private EnumComposition spellList;
    @Mock private ItemComposition grabObj;
    @Mock private Widget grabWidget;

    private SpellbookReader reader;

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
        reader = new SpellbookReader(client);

        when(client.getVarbitValue(VarbitID.SPELLBOOK)).thenReturn(0);
        when(client.getVarbitValue(VarbitID.SPELLBOOK_SUBLIST)).thenReturn(0);
        when(client.getBoostedSkillLevel(Skill.MAGIC)).thenReturn(99);

        when(client.getEnum(anyInt())).thenReturn(null);
        when(client.getEnum(net.runelite.api.EnumID.SPELLBOOKS_SUB)).thenReturn(spellbooksSub);
        when(spellbooksSub.getIntValue(0)).thenReturn(BOOK_ENUM);
        when(client.getEnum(BOOK_ENUM)).thenReturn(bookEnum);
        when(bookEnum.getIntValue(0)).thenReturn(SPELL_LIST_ENUM);
        when(client.getEnum(SPELL_LIST_ENUM)).thenReturn(spellList);

        when(spellList.size()).thenReturn(1);
        when(spellList.getIntValue(0)).thenReturn(GRAB_OBJ);
        when(client.getItemDefinition(GRAB_OBJ)).thenReturn(grabObj);
        when(grabObj.getIntValue(ParamID.SPELL_BUTTON)).thenReturn(RoomSpell.TELEKINETIC_GRAB.component());
        when(grabObj.getIntValue(ParamID.SPELL_LEVELREQ)).thenReturn(33);

        when(client.getWidget(anyInt())).thenReturn(null);
        when(client.getWidget(RoomSpell.TELEKINETIC_GRAB.component())).thenReturn(grabWidget);
    }

    @Test
    public void readsLevelRequirementFromTheCache() {
        when(grabWidget.getSpriteId()).thenReturn(GRAB_ON_SPRITE);
        SpellStatus status = reader.status(RoomSpell.TELEKINETIC_GRAB);
        assertEquals(33, status.levelRequired());
        assertEquals(99, status.magicLevel());
        assertEquals(Availability.AVAILABLE, status.availability());
    }

    @Test
    public void greyIconIsMissingRunes() {
        when(grabWidget.getSpriteId()).thenReturn(GRAB_OFF_SPRITE);
        assertEquals(Availability.MISSING_RUNES, reader.status(RoomSpell.TELEKINETIC_GRAB).availability());
    }

    @Test
    public void absentWidgetIsUnknown() {
        when(client.getWidget(RoomSpell.TELEKINETIC_GRAB.component())).thenReturn(null);
        assertEquals(Availability.UNKNOWN, reader.status(RoomSpell.TELEKINETIC_GRAB).availability());
    }

    @Test
    public void nonStandardSpellbookIsWrongSpellbook() {
        when(client.getVarbitValue(VarbitID.SPELLBOOK)).thenReturn(1);
        when(grabWidget.getSpriteId()).thenReturn(GRAB_ON_SPRITE);
        assertEquals(Availability.WRONG_SPELLBOOK, reader.status(RoomSpell.TELEKINETIC_GRAB).availability());
    }

    @Test
    public void lockedSpellIsNotUnlocked() {
        when(client.getVarbitValue(VarbitID.MAGICTRAINING_BONESPEACHES)).thenReturn(0);
        assertEquals(Availability.NOT_UNLOCKED, reader.status(RoomSpell.BONES_TO_PEACHES).availability());
    }

    @Test
    public void unlockedSpellPassesTheUnlockCheck() {
        when(client.getVarbitValue(VarbitID.MAGICTRAINING_BONESPEACHES)).thenReturn(1);
        // No spellbook entry matches Bones to Peaches in this fixture, so the level stays unread
        // and the icon (absent) decides: UNKNOWN, not NOT_UNLOCKED.
        assertEquals(Availability.UNKNOWN, reader.status(RoomSpell.BONES_TO_PEACHES).availability());
    }

    @Test
    public void levelRequirementIsReadOnceAndCached() {
        when(grabWidget.getSpriteId()).thenReturn(GRAB_ON_SPRITE);
        assertEquals(33, reader.status(RoomSpell.TELEKINETIC_GRAB).levelRequired());
        assertEquals(33, reader.status(RoomSpell.TELEKINETIC_GRAB).levelRequired());
        assertEquals(33, reader.status(RoomSpell.TELEKINETIC_GRAB).levelRequired());
        verify(grabObj, times(1)).getIntValue(ParamID.SPELL_LEVELREQ);
    }

    @Test
    public void aFailedLookupIsRetriedRatherThanCached() {
        when(client.getEnum(net.runelite.api.EnumID.SPELLBOOKS_SUB)).thenReturn(null);
        when(grabWidget.getSpriteId()).thenReturn(GRAB_ON_SPRITE);
        assertEquals(0, reader.status(RoomSpell.TELEKINETIC_GRAB).levelRequired());

        when(client.getEnum(net.runelite.api.EnumID.SPELLBOOKS_SUB)).thenReturn(spellbooksSub);
        assertEquals(33, reader.status(RoomSpell.TELEKINETIC_GRAB).levelRequired());
    }
}

package com.lazybones;

import java.util.HashSet;
import java.util.Set;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class WarningCopyTest {

    private static SpellStatus status(Availability availability, int required, int magic) {
        return new SpellStatus(RoomSpell.BONES_TO_PEACHES, availability, required, magic);
    }

    @Test
    public void castableSpellHasNothingToSay() {
        assertNull(WarningCopy.spellReason(status(Availability.AVAILABLE, 60, 99)));
        assertNull(WarningCopy.spellTitle(status(Availability.AVAILABLE, 60, 99)));
    }

    @Test
    public void titleNamesTheSpell() {
        assertEquals("Can't cast Bones to Peaches", WarningCopy.spellTitle(status(Availability.MISSING_RUNES, 60, 99)));
    }

    @Test
    public void levelReasonQuotesBothNumbers() {
        assertEquals("Needs Magic level 60 - you have 43", WarningCopy.spellReason(status(Availability.LEVEL, 60, 43)));
    }

    @Test
    public void wrongSpellbookReason() {
        assertEquals("Switch to the standard spellbook", WarningCopy.spellReason(status(Availability.WRONG_SPELLBOOK, 60, 99)));
    }

    @Test
    public void notUnlockedReasonNamesTheSpell() {
        assertEquals("Buy Bones to Peaches from the Rewards Guardian",
            WarningCopy.spellReason(status(Availability.NOT_UNLOCKED, 60, 99)));
    }

    @Test
    public void missingRunesReasonNamesTheSpell() {
        assertEquals("Out of runes for Bones to Peaches", WarningCopy.spellReason(status(Availability.MISSING_RUNES, 60, 99)));
    }

    @Test
    public void unknownAsksForTheMagicTab() {
        assertEquals("Open the Magic tab", WarningCopy.spellReason(status(Availability.UNKNOWN, 60, 99)));
    }

    @Test
    public void everyAvailabilityHasCopy() {
        Set<String> reasons = new HashSet<>();
        for (Availability availability : Availability.values()) {
            String reason = WarningCopy.spellReason(status(availability, 60, 43));
            if (availability == Availability.AVAILABLE) {
                assertNull(reason);
                continue;
            }
            assertNotNull(availability + " has no reason line", reason);
            assertTrue(availability + " has an empty reason line", reason.length() > 0);
            // Each cause needs its own wording. A constant added later and left to fall through the
            // switch would repeat whatever the default branch says, which this catches.
            assertTrue(availability + " repeats another cause's line", reasons.add(reason));
        }
    }

    @Test
    public void nullStatusHasNothingToSay() {
        assertNull(WarningCopy.spellReason(null));
        assertNull(WarningCopy.spellTitle(null));
    }

    @Test
    public void pluginOffLineDoesNotNameARoom() {
        assertEquals("Mage Training Arena plugin is off - LazyBones leaves its highlights to it",
            WarningCopy.mtaLine(MtaWarning.PLUGIN_OFF, Room.GRAVEYARD));
    }

    @Test
    public void roomOffLineNamesTheRoom() {
        assertEquals("Mage Training Arena plugin has Creature Graveyard switched off",
            WarningCopy.mtaLine(MtaWarning.ROOM_OFF, Room.GRAVEYARD));
    }

    @Test
    public void noWarningHasNoLine() {
        assertNull(WarningCopy.mtaLine(MtaWarning.NONE, Room.GRAVEYARD));
    }

    @Test
    public void everyMtaWarningHasCopy() {
        Set<String> lines = new HashSet<>();
        for (MtaWarning warning : MtaWarning.values()) {
            String line = WarningCopy.mtaLine(warning, Room.GRAVEYARD);
            if (warning == MtaWarning.NONE) {
                assertNull(line);
                continue;
            }
            // A constant added later and left to fall through mtaLine's default returns null, which
            // reads as "nothing to warn about" and the panel would stay blank.
            assertNotNull(warning + " has no line", line);
            assertTrue(warning + " has an empty line", line.length() > 0);
            assertTrue(warning + " repeats another warning's line", lines.add(line));
        }
    }
}

package com.lazybones.alchemy;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class CupboardMapTest {

    @Test
    public void startsUnsolved() {
        CupboardMap map = new CupboardMap();
        assertFalse(map.solved());
        assertEquals(-1, map.cupboardFor(AlchemyItem.EMERALD));
    }

    @Test
    public void oneSearchRevealsEveryCupboard() {
        CupboardMap map = new CupboardMap();
        map.solve(0, AlchemyItem.LEATHER_BOOTS);
        assertTrue(map.solved());
        // The order is fixed and clockwise, so cupboard n holds the nth item after the one found.
        assertEquals(0, map.cupboardFor(AlchemyItem.LEATHER_BOOTS));
        assertEquals(1, map.cupboardFor(AlchemyItem.ADAMANT_KITESHIELD));
        assertEquals(2, map.cupboardFor(AlchemyItem.ADAMANT_MED_HELM));
        assertEquals(3, map.cupboardFor(AlchemyItem.EMERALD));
        assertEquals(4, map.cupboardFor(AlchemyItem.RUNE_LONGSWORD));
        assertEquals(5, map.cupboardFor(AlchemyItem.EMPTY));
    }

    @Test
    public void solvesFromAnyCupboardAndAnyItem() {
        for (int cupboard = 0; cupboard < 6; cupboard++) {
            for (AlchemyItem found : AlchemyItem.values()) {
                CupboardMap map = new CupboardMap();
                map.solve(cupboard, found);
                assertEquals(found + " from cupboard " + cupboard,
                    cupboard, map.cupboardFor(found));
                // Every item lands in exactly one cupboard, and every cupboard is used once.
                boolean[] used = new boolean[6];
                for (AlchemyItem item : AlchemyItem.values()) {
                    int at = map.cupboardFor(item);
                    assertFalse(item + " shares a cupboard", used[at]);
                    used[at] = true;
                }
            }
        }
    }

    @Test
    public void invalidateForgetsEverything() {
        CupboardMap map = new CupboardMap();
        map.solve(2, AlchemyItem.EMERALD);
        map.invalidate();
        assertFalse(map.solved());
        assertEquals(-1, map.cupboardFor(AlchemyItem.EMERALD));
    }

    @Test
    public void solvingAgainReplacesTheOldRotation() {
        CupboardMap map = new CupboardMap();
        map.solve(0, AlchemyItem.LEATHER_BOOTS);
        map.solve(0, AlchemyItem.EMERALD);
        // Every slot follows the new rotation, not just the two that moved.
        assertEquals(0, map.cupboardFor(AlchemyItem.EMERALD));
        assertEquals(1, map.cupboardFor(AlchemyItem.RUNE_LONGSWORD));
        assertEquals(2, map.cupboardFor(AlchemyItem.EMPTY));
        assertEquals(3, map.cupboardFor(AlchemyItem.LEATHER_BOOTS));
        assertEquals(4, map.cupboardFor(AlchemyItem.ADAMANT_KITESHIELD));
        assertEquals(5, map.cupboardFor(AlchemyItem.ADAMANT_MED_HELM));
    }

    @Test
    public void itemTextMatchesEitherWording() {
        // The chat line and the interface row do not use identical wording, so matching is on a
        // distinctive keyword rather than the whole string.
        assertEquals(AlchemyItem.LEATHER_BOOTS, AlchemyItem.fromText("Leather boots"));
        assertEquals(AlchemyItem.LEATHER_BOOTS, AlchemyItem.fromText("leather boots"));
        assertEquals(AlchemyItem.ADAMANT_KITESHIELD, AlchemyItem.fromText("Adamant kiteshield"));
        assertEquals(AlchemyItem.ADAMANT_KITESHIELD, AlchemyItem.fromText("adamant kite shield"));
        assertEquals(AlchemyItem.ADAMANT_MED_HELM, AlchemyItem.fromText("Adamant med helm"));
        assertEquals(AlchemyItem.ADAMANT_MED_HELM, AlchemyItem.fromText("adamant medium helmet"));
        // The arena plugin shortens this row to "Helm" with no prefix; the keyword must still catch it.
        assertEquals(AlchemyItem.ADAMANT_MED_HELM, AlchemyItem.fromText("Helm"));
        assertEquals(AlchemyItem.EMERALD, AlchemyItem.fromText("Emerald"));
        assertEquals(AlchemyItem.RUNE_LONGSWORD, AlchemyItem.fromText("Rune longsword"));
        assertEquals(AlchemyItem.RUNE_LONGSWORD, AlchemyItem.fromText("rune long sword"));
    }

    @Test
    public void unknownTextMatchesNothing() {
        assertNull(AlchemyItem.fromText("dragon scimitar"));
        assertNull(AlchemyItem.fromText(""));
        assertNull(AlchemyItem.fromText(null));
    }

    @Test
    public void everyRealItemHasADistinctId() {
        for (AlchemyItem a : AlchemyItem.values()) {
            for (AlchemyItem b : AlchemyItem.values()) {
                if (a != b && a != AlchemyItem.EMPTY && b != AlchemyItem.EMPTY) {
                    assertFalse(a + " and " + b + " share an item id", a.itemId() == b.itemId());
                }
            }
        }
    }
}

