import static org.mockito.Mockito.when;

public class FreeItemReaderTest {

    private static final int[] ARROWS = {
        InterfaceID.MagictrainingAlchem.MAGICTRAIN_ARROW1,
        InterfaceID.MagictrainingAlchem.MAGICTRAIN_ARROW2,
        InterfaceID.MagictrainingAlchem.MAGICTRAIN_ARROW3,
        InterfaceID.MagictrainingAlchem.MAGICTRAIN_ARROW4,
        InterfaceID.MagictrainingAlchem.MAGICTRAIN_ARROW5,
    };
    private static final int[] ITEMS = {
        InterfaceID.MagictrainingAlchem.MAGICTRAIN_ALCHEM_ITEM1,
        InterfaceID.MagictrainingAlchem.MAGICTRAIN_ALCHEM_ITEM2,
        InterfaceID.MagictrainingAlchem.MAGICTRAIN_ALCHEM_ITEM3,
        InterfaceID.MagictrainingAlchem.MAGICTRAIN_ALCHEM_ITEM4,
        InterfaceID.MagictrainingAlchem.MAGICTRAIN_ALCHEM_ITEM5,
    };
    private static final String[] ROW_TEXT = {
        "Leather boots", "Adamant kiteshield", "Adamant med helm", "Emerald", "Rune longsword",
    };

    @Mock private Client client;
    private FreeItemReader reader;

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
        reader = new FreeItemReader(client);
        doReturn(null).when(client).getWidget(anyInt());
        for (int i = 0; i < 5; i++) {
            doReturn(textWidget(ROW_TEXT[i])).when(client).getWidget(ITEMS[i]);
            doReturn(hiddenWidget()).when(client).getWidget(ARROWS[i]);
        }
    }

    private Widget textWidget(String text) {
        Widget w = org.mockito.Mockito.mock(Widget.class);
        when(w.getText()).thenReturn(text);
        return w;
    }

    private Widget hiddenWidget() {
        Widget w = org.mockito.Mockito.mock(Widget.class);
        when(w.isHidden()).thenReturn(true);
        return w;
    }

    private void showArrow(int row) {
        Widget w = org.mockito.Mockito.mock(Widget.class);
        when(w.isHidden()).thenReturn(false);
        doReturn(w).when(client).getWidget(ARROWS[row]);
    }

    @Test
    public void noArrowShowingMeansNothingIsFree() {
        assertTrue(reader.freeItems().isEmpty());
    }

    @Test
    public void oneArrowNamesItsRowsItem() {
        showArrow(3);
        assertEquals(java.util.Collections.singletonList(AlchemyItem.EMERALD), reader.freeItems());
    }

    @Test
    public void everyRowMapsToItsOwnItem() {
        AlchemyItem[] expected = {
            AlchemyItem.LEATHER_BOOTS, AlchemyItem.ADAMANT_KITESHIELD,
            AlchemyItem.ADAMANT_MED_HELM, AlchemyItem.EMERALD, AlchemyItem.RUNE_LONGSWORD,
        };
        for (int row = 0; row < 5; row++) {
            setUp();
            showArrow(row);
            assertEquals("row " + row, java.util.Collections.singletonList(expected[row]), reader.freeItems());
        }
    }

    @Test
    public void severalArrowsReturnSeveralItems() {
        showArrow(0);
        showArrow(4);
        List<AlchemyItem> free = reader.freeItems();
        assertEquals(2, free.size());
        assertTrue(free.contains(AlchemyItem.LEATHER_BOOTS));
        assertTrue(free.contains(AlchemyItem.RUNE_LONGSWORD));
    }

    @Test
    public void aMissingArrowWidgetIsNotFree() {
        doReturn(null).when(client).getWidget(ARROWS[2]);
        assertTrue(reader.freeItems().isEmpty());
    }

    @Test
    public void anArrowOnAnUnreadableRowIsIgnored() {
        doReturn(textWidget("something else entirely")).when(client).getWidget(ITEMS[1]);
        showArrow(1);
        assertTrue(reader.freeItems().isEmpty());
    }
}

package com.lazybones.enchant;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class BonusShapeTrackerTest {

    @Test
    public void startsKnowingNothing() {
        BonusShapeTracker tracker = new BonusShapeTracker();
        assertNull(tracker.shape());
        assertFalse(tracker.known());
    }

    @Test
    public void theFirstReadNamesTheShapeButNotTheTiming() {
        // Walking in mid-window, there is no way to know how much of it is gone.
        BonusShapeTracker tracker = new BonusShapeTracker();
        tracker.observe(Shape.CUBE, 100);
        assertEquals(Shape.CUBE, tracker.shape());
        assertFalse("the window start is still unknown", tracker.known());
    }

    @Test
    public void aChangeStampsTheWindowStart() {
        BonusShapeTracker tracker = new BonusShapeTracker();
        tracker.observe(Shape.CUBE, 100);
        tracker.observe(Shape.CYLINDER, 130);
        assertEquals(Shape.CYLINDER, tracker.shape());
        assertTrue(tracker.known());
        assertEquals(0, tracker.elapsedTicks(130));
        assertEquals(7, tracker.elapsedTicks(137));
    }

    @Test
    public void anUnchangedReadDoesNotRestartTheWindow() {
        BonusShapeTracker tracker = new BonusShapeTracker();
        tracker.observe(Shape.CUBE, 100);
        tracker.observe(Shape.CYLINDER, 130);
        tracker.observe(Shape.CYLINDER, 131);
        tracker.observe(Shape.CYLINDER, 132);
        assertEquals(2, tracker.elapsedTicks(132));
    }

    @Test
    public void anUnreadableIndicatorChangesNothing() {
        BonusShapeTracker tracker = new BonusShapeTracker();
        tracker.observe(Shape.CUBE, 100);
        tracker.observe(Shape.CYLINDER, 130);
        tracker.observe(null, 135);
        tracker.observe(null, 136);
        assertEquals(Shape.CYLINDER, tracker.shape());
        assertTrue("a read we could not parse must not lose the window either", tracker.known());
        assertEquals(7, tracker.elapsedTicks(137));
    }

    @Test
    public void aLaterChangeReAnchorsTheTiming() {
        BonusShapeTracker tracker = new BonusShapeTracker();
        tracker.observe(Shape.CUBE, 100);
        tracker.observe(Shape.CYLINDER, 130);
        tracker.observe(Shape.PENTAMID, 170);
        assertEquals(Shape.PENTAMID, tracker.shape());
        assertEquals(0, tracker.elapsedTicks(170));
    }

    @Test
    public void theSameShapeReturningIsStillTwoChanges() {
        // Cube to cylinder and back: two resets, and the second is the one that counts.
        BonusShapeTracker tracker = new BonusShapeTracker();
        tracker.observe(Shape.CUBE, 100);
        tracker.observe(Shape.CYLINDER, 140);
        tracker.observe(Shape.CUBE, 180);
        assertEquals(Shape.CUBE, tracker.shape());
        assertEquals(0, tracker.elapsedTicks(180));
    }

    @Test
    public void withNoWindowStartTheElapsedCountIsZero() {
        // Handing back the raw tick count would be a large number that survives the modulo downstream
        // and reads as a perfectly ordinary point in the window.
        BonusShapeTracker fresh = new BonusShapeTracker();
        assertEquals(0, fresh.elapsedTicks(4000));

        BonusShapeTracker walkedIn = new BonusShapeTracker();
        walkedIn.observe(Shape.CUBE, 4000);
        assertEquals(0, walkedIn.elapsedTicks(4000));
        assertEquals(0, walkedIn.elapsedTicks(4037));
    }

    @Test
    public void clearForgetsEverything() {
        BonusShapeTracker tracker = new BonusShapeTracker();
        tracker.observe(Shape.CUBE, 100);
        tracker.observe(Shape.CYLINDER, 130);
        tracker.clear();
        assertNull(tracker.shape());
        assertFalse(tracker.known());
    }
}

package com.lazybones.enchant;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class PickupCalculatorTest {

    // The defaults: a 24 second window at 0.6s per tick, a 3 tick enchant, a 1 tick pickup,
    // and 4 ticks kept back to reach the next pile and pick the spell.
    private static final TickModel DEFAULTS = new TickModel(40, 3, 1, 4);

    @Test
    public void aFreshWindowHasItsWholeLength() {
        assertEquals(40, PickupCalculator.ticksLeft(0, DEFAULTS));
    }

    @Test
    public void timeRunsDown() {
        assertEquals(30, PickupCalculator.ticksLeft(10, DEFAULTS));
        assertEquals(1, PickupCalculator.ticksLeft(39, DEFAULTS));
    }

    @Test
    public void anUnseenResetRollsOverInsteadOfStalling() {
        // A window can end without the indicator text changing, so elapsed time past the window
        // wraps rather than clamping - otherwise the count would sit at zero until the player left.
        assertEquals(40, PickupCalculator.ticksLeft(40, DEFAULTS));
        assertEquals(35, PickupCalculator.ticksLeft(45, DEFAULTS));
        assertEquals(40, PickupCalculator.ticksLeft(80, DEFAULTS));
    }

    @Test
    public void aTickCounterResetDoesNotOverrunTheWindow() {
        // The client's tick count restarts at a hop or a relog, which leaves the recorded window
        // start ahead of the current tick. Without the sign correction that reads as more time left
        // than the window even has, and the bar would draw past full.
        assertEquals(5, PickupCalculator.ticksLeft(-5, DEFAULTS));
        assertEquals(40, PickupCalculator.ticksLeft(-40, DEFAULTS));
        for (int elapsed = -80; elapsed <= 80; elapsed++) {
            int left = PickupCalculator.ticksLeft(elapsed, DEFAULTS);
            assertTrue("elapsed " + elapsed + " gave " + left, left >= 1 && left <= 40);
        }
    }

    @Test
    public void emptyHandedAtTheStartTakesAsManyAsFit() {
        // (40 - 4) / (1 + 3) = 9
        assertEquals(9, PickupCalculator.pickups(40, 0, DEFAULTS));
    }

    @Test
    public void everyHeldShapeCostsAnEnchant() {
        // 40 - 4 - (2 * 3) = 30, / 4 = 7
        assertEquals(7, PickupCalculator.pickups(40, 2, DEFAULTS));
    }

    @Test
    public void aFullHandLeavesNothingToPickUp() {
        // 12 held shapes need 36 ticks to enchant, which is the whole window past the buffer.
        assertEquals(0, PickupCalculator.pickups(40, 12, DEFAULTS));
    }

    @Test
    public void theCountNeverGoesNegative() {
        assertEquals(0, PickupCalculator.pickups(40, 99, DEFAULTS));
        assertEquals(0, PickupCalculator.pickups(0, 0, DEFAULTS));
    }

    @Test
    public void theBufferIsHeldBackToTheEnd() {
        // 8 ticks left, buffer 4: only 4 usable, which is exactly one pick-and-enchant.
        assertEquals(1, PickupCalculator.pickups(8, 0, DEFAULTS));
        // 7 left: 3 usable, not enough for the 4 tick cycle.
        assertEquals(0, PickupCalculator.pickups(7, 0, DEFAULTS));
    }

    @Test
    public void aBiggerBufferStopsSooner() {
        TickModel cautious = new TickModel(40, 3, 1, 12);
        assertEquals(7, PickupCalculator.pickups(40, 0, cautious));
    }

    @Test
    public void aSlowerEnchantFitsFewer() {
        TickModel slow = new TickModel(40, 5, 1, 4);
        // (40 - 4) / (1 + 5) = 6
        assertEquals(6, PickupCalculator.pickups(40, 0, slow));
    }

    @Test
    public void aShorterWindowFitsFewer() {
        TickModel short20 = new TickModel(20, 3, 1, 4);
        assertEquals(20, PickupCalculator.ticksLeft(0, short20));
        assertEquals(4, PickupCalculator.pickups(20, 0, short20));
    }
}

package com.lazybones.enchant;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;

public class ShapeTest {

    @Test
    public void pilesResolveToTheirShape() {
        for (Shape shape : Shape.values()) {
            assertEquals(shape, Shape.fromPileObjectId(shape.pileObjectId()));
        }
    }

    @Test
    public void anythingElseIsNotAPile() {
        assertNull(Shape.fromPileObjectId(0));
        assertNull(Shape.fromPileObjectId(23698)); // the deposit hole, not a pile
    }

    @Test
    public void everyShapeHasDistinctIds() {
        for (Shape a : Shape.values()) {
            for (Shape b : Shape.values()) {
                if (a != b) {
                    assertFalse(a + " and " + b + " share an item id", a.itemId() == b.itemId());
                    assertFalse(a + " and " + b + " share a pile id", a.pileObjectId() == b.pileObjectId());
                }
            }
        }
    }
}
